    ("faq",                  "FAQ",                          "solo",       True,  "Content"),
    ("blog",                 "Blog",                         "solo",       True,  "Content"),
    ("events",               "Events",                       "solo",       True,  "Content"),
    ("services",             "Services",                     "solo",       True,  "Content"),
    ("media",                "Media library",                "solo",       True,  "Content"),
