    ("marketing_insights",   "Marketing insights",           "growth",     True,  "Insights"),
    ("admin_chat",           "Admin AI chat",                "solo",       True,  "AI"),
    ("chatbot",              "Chatbot settings",             "solo",       True,  "AI"),
    ("knowledge_cache",      "Knowledge cache (RAG)",        "growth",     True,  "AI"),
