# ---- Public — visitor-facing presentation fetch -----------------------------

@app.route("/api/presentations/<slug>", methods=["GET"])
def public_get_presentation(slug):
    """GET /api/presentations/<slug> — fetch one enabled deck for the
    visitor-side overlay player. Returns deck metadata + ordered slides
    including narration_text (the voice agent will speak it).

    Uses _resolve_presentation_slug so that the visitor agent can emit
    an abbreviated slug (e.g. 'thetasync' for 'thetasync-deck') and
    still successfully open the deck instead of silently 404-ing."""
    p = _resolve_presentation_slug(slug)
    if not p:
        return jsonify({"error": "Presentation not found"}), 404
    slides = query_db(
        "SELECT id, order_index, title, body, image_url, narration_text "
        "FROM presentation_slides WHERE presentation_id = %s "
        "ORDER BY order_index ASC, id ASC",
        (p["id"],),
    ) or []
    return jsonify({
        "slug": p["slug"],
        "title": p["title"],
        "description": p["description"],
        "cover_image_url": p["cover_image_url"],
        "auto_play": bool(p["auto_play"]),
        # display_mode tells the player whether to overlay the parsed
        # title+body styling ('rich'), or just show the original imported
        # slide image full-bleed with no text on top ('original').
        "display_mode": (p.get("display_mode") or "rich"),
        "ai_narrate_mode": (p.get("ai_narrate_mode") or "manual"),
        "slides": slides,
    })


