# MARKETING INSIGHTS + DRAFTS — read endpoints for the
# "Marketing Insights" admin tab. The admin AI populates these
# tables via _admin_tool_analyze_* (insights cache) and
# propose_draft_blog_post / propose_draft_faq_entry (pending
# rows). The tab below is purely a viewer — approve / reject
# of drafts goes through the existing chat-action endpoints.
# =============================================================

@app.route("/admin/api/marketing/insights", methods=["GET"])
@admin_required
def admin_list_marketing_insights():
    """GET /admin/api/marketing/insights — list cached insight runs.
    Optional ?type=<insight_type> filters to one kind (chat_topics /
    page_library / seo_gaps). Default 50 most recent."""
    insight_type = (request.args.get("type") or "").strip()[:50]
    try:
        limit = max(1, min(int(request.args.get("limit") or 50), 200))
    except Exception:
        limit = 50
    where = ["1=1"]
    args = []
    if insight_type:
        where.append("insight_type = %s")
        args.append(insight_type)
    rows = query_db(
        "SELECT id, insight_type, window_start, window_end, "
        "       summary_json, notes, created_at "
        "FROM marketing_insights_log WHERE " + " AND ".join(where)
        + " ORDER BY created_at DESC LIMIT %s",
        tuple(args + [limit]),
    ) or []
    out = []
    for r in rows:
        out.append({
            "id": r["id"],
            "insight_type": r.get("insight_type") or "",
            "window_start": (r["window_start"].isoformat()
                              if r.get("window_start") else None),
            "window_end": (r["window_end"].isoformat()
                            if r.get("window_end") else None),
            "summary_json": r.get("summary_json") or {},
            "notes": r.get("notes") or "",
            "created_at": (r["created_at"].isoformat()
                           if r.get("created_at") else None),
        })
    return jsonify({"insights": out, "count": len(out)})


@app.route("/admin/api/marketing/drafts", methods=["GET"])
@admin_required
def admin_list_marketing_drafts():
    """GET /admin/api/marketing/drafts — list AI-drafted blog / FAQ
    entries the admin AI has queued for approval. Wraps the existing
    admin_pending_actions table; approve / reject still go through
    /admin/api/chat/action/<id>/approve | /reject.

    Status semantics: rows start at 'pending', the approve endpoint
    transitions them to 'executed' on success or 'failed' on error,
    and the reject endpoint transitions them to 'rejected'. We accept
    'approved' as a UI-friendly alias for 'executed' so the dashboard
    filter labels can read naturally."""
    status_raw = (request.args.get("status") or "pending").strip()[:20]
    # Allowlist + 'approved' alias → 'executed' (the real DB value).
    valid_status = {"pending", "executed", "rejected", "failed"}
    if status_raw == "approved":
        status = "executed"
    elif status_raw in valid_status:
        status = status_raw
    else:
        status = "pending"
    try:
        limit = max(1, min(int(request.args.get("limit") or 50), 200))
    except Exception:
        limit = 50
    rows = query_db(
        "SELECT id, action_type, target_table, target_id, "
        "       payload_json, preview, status, error_text, "
        "       created_at, decided_at "
        "FROM admin_pending_actions "
        "WHERE target_table IN ('blog_posts','faqs') "
        "  AND status = %s "
        "ORDER BY created_at DESC LIMIT %s",
        (status, limit),
    ) or []
    out = []
    for r in rows:
        payload = r.get("payload_json") or {}
        if isinstance(payload, str):
            try: payload = json.loads(payload)
            except Exception: payload = {}
        fields = (payload.get("fields") or {}) if isinstance(payload, dict) else {}
        out.append({
            "id": r["id"],
            "kind": ("blog" if r.get("target_table") == "blog_posts"
                     else "faq" if r.get("target_table") == "faqs"
                     else (r.get("target_table") or "")),
            "target_table": r.get("target_table") or "",
            "target_id": r.get("target_id"),
            "title": (fields.get("title") or fields.get("question")
                      or "(untitled)"),
            "body_preview": ((fields.get("content") or fields.get("answer")
                              or "")[:400]),
            "preview": r.get("preview") or "",
            "status": r.get("status") or "",
            "error_text": r.get("error_text") or "",
            "created_at": (r["created_at"].isoformat()
                           if r.get("created_at") else None),
            "decided_at": (r["decided_at"].isoformat()
                           if r.get("decided_at") else None),
        })
    return jsonify({"drafts": out, "count": len(out)})


@app.route("/api/generated-pages/by-slug/<slug>")
def api_generated_page_by_slug(slug):
    """
    GET /api/generated-pages/by-slug/<slug>

    Returns a published AI page's HTML + title as JSON, so the chat UI
    can render it instantly in the immersive page overlay (instead of
    a full-page navigation). This is the back-end half of the
    showSavedPage command — the AI hands back a slug, the frontend
    fetches the saved markup and displays it without ever asking the
    model to regenerate the HTML.

    Slug shape is validated up front for defense-in-depth: lowercase
    alphanumerics and hyphens only, max 200 chars (matches the slug
    column). Only pages with status='published' are returned.
    """
    if not slug or not _GENERATED_PAGE_SLUG_RE.match(slug):
        return jsonify({"error": "Invalid slug"}), 400

    page = query_db(
        "SELECT id, title, html, slug FROM generated_pages "
        "WHERE slug = %s AND status = 'published'",
        (slug,), fetchone=True
    )

    # Fuzzy fallback. Saved page slugs include a trailing "-<timestamp>"
    # suffix appended at creation time (e.g. "wine-cellar-1777058143"),
    # but the model sometimes emits the bare stem ("wine-cellar") or a
    # stem from an older draft that has since been re-published with a
    # different timestamp. Rather than failing the request and forcing
    # the visitor to rephrase, we look for the most recently updated
    # PUBLISHED page whose slug shares the same stem and return that.
    # We only match on the stem (everything before the final "-<digits>")
    # so we never silently swap to an unrelated page that happens to
    # share a prefix.
    if not page:
        # Strip a single trailing "-<digits>" group to get the stem.
        # If the requested slug has no timestamp suffix, the stem is
        # just the slug itself. Stem must be non-empty after stripping.
        stem = re.sub(r"-\d+$", "", slug).strip("-")
        if stem and _GENERATED_PAGE_SLUG_RE.match(stem):
            # Match published pages whose slug equals the stem OR is the
            # stem followed by a hyphen and ONLY digits (the timestamp
            # suffix our slug-builder appends at create time). We require
            # digits-only so a stem like "wine" can't accidentally match
            # "wine-tour-1234" — only "wine-1234" / "wine-99" etc. count
            # as the same page. Postgres' `~` operator runs the regex.
            stem_regex = "^" + re.escape(stem) + "-[0-9]+$"
            page = query_db(
                "SELECT id, title, html, slug FROM generated_pages "
                "WHERE status = 'published' "
                "AND (slug = %s OR slug ~ %s) "
                "ORDER BY updated_at DESC LIMIT 1",
                (stem, stem_regex), fetchone=True
            )
            if page:
                app.logger.info(
                    "by-slug fuzzy match: requested '%s' -> served '%s'",
                    slug, page.get("slug", "")
                )

    if not page:
        return jsonify({"error": "Page not found"}), 404
    # Reuse instrumentation — bumps the counter the admin AI's
    # analyze_page_library / suggest_seo_improvements tools read to
    # distinguish "earning its keep" pages from "never served" ones.
    try:
        execute_db(
            "UPDATE generated_pages "
            "SET reuse_count = reuse_count + 1, last_served_at = NOW() "
            "WHERE id = %s",
            (page["id"],),
        )
    except Exception:
        pass
    return jsonify({
        "id": page["id"],
        "title": page.get("title", ""),
        "slug": page.get("slug", ""),
        "html": page.get("html", ""),
    })


@app.route("/page/<slug>")
def public_generated_page(slug):
    """GET /page/<slug> — Render a published AI-generated page."""
    page = query_db("SELECT * FROM generated_pages WHERE slug = %s AND status = 'published'", (slug,), fetchone=True)
    if not page:
        return "Page not found", 404
    # Reuse instrumentation — same counter the JSON serve increments,
    # so direct URL visits and AI-driven showSavedPage navigations
    # both register as "served". Wrapped in try/except so a counter
    # failure can never block rendering the page.
    try:
        execute_db(
            "UPDATE generated_pages "
            "SET reuse_count = reuse_count + 1, last_served_at = NOW() "
            "WHERE id = %s",
            (page["id"],),
        )
    except Exception:
        pass
    return f"""<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>{page['title'].replace('&','&amp;').replace('<','&lt;').replace('>','&gt;').replace('"','&quot;')}</title>
    <link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;700&family=DM+Sans:wght@300;400;500;700&display=swap" rel="stylesheet">
    <style>
        body {{ margin: 0; padding: 0; background: #060b14; color: #e4e4e7; font-family: 'DM Sans', sans-serif; min-height: 100vh; display: flex; align-items: center; justify-content: center; }}
    </style>
</head>
<body>
    {page['html']}
</body>
</html>"""


