@app.route("/api/services/<string:slug>/availability", methods=["GET"])
def api_service_availability(slug):
    """?start=YYYY-MM-DD&end=YYYY-MM-DD — returns day buckets with open slots."""
    svc = query_db(
        "SELECT * FROM services WHERE slug = %s AND is_active = TRUE",
        (slug,), fetchone=True,
    )
    if not svc:
        return jsonify({"error": "Service not found"}), 404
    if not svc["requires_calendar"]:
        return jsonify({"requires_calendar": False, "days": []})
    from datetime import date, timedelta
    today = date.today()
    start = request.args.get("start") or today.isoformat()
    end = request.args.get("end") or (today + timedelta(days=30)).isoformat()
    days = _compute_availability(svc["id"], start, end)
    return jsonify({"requires_calendar": True, "days": days})


# --------------- Public: booking dispatcher ---------------

def _send_booking_confirmation(booking, service):
    """Best-effort: email the client after successful booking creation/confirmation.

    Quietly no-ops if Resend isn't configured. The messaging module already
    handles its own failures and logging, so we only catch unexpected
    exceptions here so a confirmation hiccup never breaks the booking flow.
    """
    if not booking or not service:
        return
    try:
        to = booking.get("client_email")
        if not to:
            return
        money = lambda c: f"${(int(c) / 100):.2f} {service['currency'].upper()}"
        lines = [
            f"Hi {booking.get('client_name', '')},",
            "",
            f"Your booking for {service['name']} has been received.",
        ]
        if booking.get("scheduled_date"):
            lines.append(
                f"When: {booking['scheduled_date']} "
                f"{booking.get('scheduled_start') or ''}".strip()
            )
        if booking.get("addon_snapshot"):
            try:
                addons = booking["addon_snapshot"]
                if isinstance(addons, str):
                    addons = json.loads(addons)
                if addons:
                    lines.append("Add-ons:")
                    for a in addons:
                        lines.append(f"  - {a['name']} ({money(a['price_cents'])})")
            except (ValueError, KeyError, TypeError):
                pass
        if booking.get("total_cents"):
            lines.append(f"Total: {money(booking['total_cents'])}")
        if booking.get("amount_paid_cents"):
            lines.append(f"Paid: {money(booking['amount_paid_cents'])}")
        if service["pricing_model"] == "contract" and service.get("contract_template_url"):
            lines.append("")
            lines.append(
                f"Please download, sign, and return your contract: "
                f"{request.host_url.rstrip('/')}{service['contract_template_url']}"
            )
            lines.append(
                f"Upload your signed contract here: "
                f"{request.host_url.rstrip('/')}/booking/{booking['booking_token']}/contract"
            )
        lines += ["", "Thank you!"]
        messaging.send_email(
            to,
            subject=f"Booking confirmation — {service['name']}",
            text=("\n".join(lines)),
            html=None,
        )
    except Exception as e:
        app.logger.warning("Booking confirmation email failed: %s", e)


def _ensure_service_booking_form(service):
    """Make sure there is a custom_forms row for this service so its
    bookings (and abandoned attempts) show up in the Forms tab.

    Returns the form id, or None if the row could not be created.
    Idempotent — safe to call on every booking and partial save.
    """
    if not service:
        return None
    svc_id = service.get("id")
    svc_name = (service.get("name") or "").strip() or f"Service #{svc_id}"
    svc_slug = (service.get("slug") or "").strip() or f"service-{svc_id}"
    form_slug = f"service-booking-{svc_slug}"[:100]

    existing = query_db(
        "SELECT id FROM custom_forms WHERE form_type = 'service_booking' "
        "AND linked_service_id = %s LIMIT 1",
        (svc_id,), fetchone=True,
    )
    if existing:
        return existing["id"]

    # Re-use a row pre-existing under the same slug if any (e.g. re-created
    # service with same slug) — bind it to this service.
    by_slug = query_db(
        "SELECT id FROM custom_forms WHERE slug = %s LIMIT 1",
        (form_slug,), fetchone=True,
    )
    if by_slug:
        execute_db(
            "UPDATE custom_forms SET form_type = 'service_booking', "
            "linked_service_id = %s, name = %s, updated_at = NOW() "
            "WHERE id = %s",
            (svc_id, f"Service Booking — {svc_name}", by_slug["id"]),
        )
        return by_slug["id"]

    try:
        result = execute_db(
            """INSERT INTO custom_forms
               (name, slug, description, status, submit_button_text,
                success_message, sort_order, form_type, linked_service_id)
               VALUES (%s, %s, %s, 'active', 'Book',
                       'Thanks! Your booking request was received.',
                       COALESCE((SELECT MAX(sort_order)+1 FROM custom_forms), 0),
                       'service_booking', %s)
               RETURNING id""",
            (
                f"Service Booking — {svc_name}",
                form_slug,
                f"Auto-managed form that mirrors bookings + abandoned carts for the '{svc_name}' service.",
                svc_id,
            ),
        )
        return result["id"] if result else None
    except Exception:
        # Race / duplicate-slug — re-query and bind.
        again = query_db(
            "SELECT id FROM custom_forms WHERE slug = %s LIMIT 1",
            (form_slug,), fetchone=True,
        )
        return again["id"] if again else None


def _booking_submission_payload(svc, booking_dict, raw_data, addons):
    """Shape the JSONB body we store on form_submissions for a service
    booking, in the same flat key/value style the regular Forms UI
    already renders. Keeping the same keys for both partial saves and
    final submissions means abandoned-cart recovery just works."""
    addons_label = ", ".join(a.get("name", "") for a in (addons or [])) if addons else ""
    return {
        "service_name":     svc.get("name", ""),
        "service_slug":     svc.get("slug", ""),
        "pricing_model":    svc.get("pricing_model", ""),
        "client_name":      (raw_data or {}).get("client_name", "")
                            or (booking_dict or {}).get("client_name", ""),
        "client_email":     (raw_data or {}).get("client_email", "")
                            or (booking_dict or {}).get("client_email", ""),
        "client_phone":     (raw_data or {}).get("client_phone", "")
                            or (booking_dict or {}).get("client_phone", ""),
        "notes":            (raw_data or {}).get("notes", "")
                            or (booking_dict or {}).get("notes", ""),
        "scheduled_date":   str((booking_dict or {}).get("scheduled_date")
                                or (raw_data or {}).get("scheduled_date") or ""),
        "scheduled_start":  str((booking_dict or {}).get("scheduled_start")
                                or (raw_data or {}).get("scheduled_start") or ""),
        "addons":           addons_label,
        "total_cents":      int((booking_dict or {}).get("total_cents") or 0),
        "currency":         (booking_dict or {}).get("currency", svc.get("currency") or "usd"),
        "booking_token":    (booking_dict or {}).get("booking_token", ""),
    }


@app.route("/api/services/<string:slug>/booking-partial", methods=["POST"])
def api_service_booking_partial(slug):
    """POST /api/services/<slug>/booking-partial — Save partial booking
    data so the Forms tab can show abandoned carts. Mirrors the
    /api/forms/<slug>/partial flow but is keyed off the service slug."""
    svc = query_db(
        "SELECT id, slug, name, pricing_model, currency FROM services "
        "WHERE slug = %s AND is_active = TRUE",
        (slug,), fetchone=True,
    )
    if not svc:
        return jsonify({"error": "Service not found"}), 404

    data = request.get_json() or {}
    session_id = (data.get("session_id") or "").strip()
    if not session_id:
        return jsonify({"error": "session_id required"}), 400

    fields = data.get("fields") or {}
    # Stamp service identifiers onto every partial save so admin's
    # submissions list is self-explanatory.
    fields = dict(fields)
    fields.setdefault("service_name", svc.get("name", ""))
    fields.setdefault("service_slug", svc.get("slug", ""))
    fields.setdefault("pricing_model", svc.get("pricing_model", ""))

    form_id = _ensure_service_booking_form(svc)
    if not form_id:
        return jsonify({"error": "Could not register booking form"}), 500

    ua_string = request.headers.get("User-Agent", "")
    ip = (request.headers.get("X-Forwarded-For", request.remote_addr or "") or "").split(",")[0].strip()[:45]
    browser, os_name, device = _parse_ua(ua_string)

    existing = query_db(
        "SELECT id, status FROM form_submissions "
        "WHERE form_id = %s AND session_id = %s "
        "ORDER BY submitted_at DESC LIMIT 1",
        (form_id, session_id), fetchone=True,
    )
    if existing and existing["status"] == "partial":
        execute_db(
            "UPDATE form_submissions SET submission_data = %s::jsonb, "
            "updated_at = NOW() WHERE id = %s",
            (json.dumps(fields), existing["id"]),
        )
        return jsonify({"success": True, "id": existing["id"], "action": "updated"})
    if existing and existing["status"] != "partial":
        # Already booked in this session — don't reopen as partial.
        return jsonify({"success": True, "id": existing["id"], "action": "already_submitted"})

    result = execute_db(
        """INSERT INTO form_submissions
            (form_id, submission_data, status, device_type, user_agent,
             referrer_url, utm_source, utm_medium, utm_campaign, utm_term, utm_content,
             page_url, ip_address, browser, os, screen_resolution, language, session_id)
           VALUES (%s, %s::jsonb, 'partial', %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
           RETURNING id""",
        (
            form_id, json.dumps(fields), device, ua_string[:500],
            data.get("referrer", ""),
            data.get("utm_source", ""), data.get("utm_medium", ""),
            data.get("utm_campaign", ""), data.get("utm_term", ""),
            data.get("utm_content", ""),
            data.get("page_url", ""), ip, browser, os_name,
            data.get("screen_resolution", ""), data.get("language", ""),
            session_id,
        ),
    )
    return jsonify({"success": True, "id": result["id"] if result else None, "action": "created"}), 201


@app.route("/api/services/<string:slug>/book", methods=["POST"])
def api_book_service(slug):
    """Create a booking. Dispatches per pricing model and returns either:
       * {status: 'confirmed', booking_token, ...}                — RSVP / contract
       * {status: 'awaiting_payment', checkout_url, booking_token} — Stripe
    """
    svc = query_db(
        "SELECT * FROM services WHERE slug = %s AND is_active = TRUE",
        (slug,), fetchone=True,
    )
    if not svc:
        return jsonify({"error": "Service not found"}), 404

    data = request.get_json() or {}
    name = (data.get("client_name") or "").strip()
    email = (data.get("client_email") or "").strip()
    if not name or not email:
        return jsonify({"error": "Name and email are required"}), 400

    addon_ids = [int(x) for x in (data.get("addon_ids") or []) if str(x).isdigit()]
    addons = []
    if addon_ids:
        addons = query_db(
            "SELECT id, name, price_cents FROM service_addons "
            "WHERE service_id = %s AND id = ANY(%s) AND is_active = TRUE",
            (svc["id"], addon_ids),
        ) or []
    addons_total = sum(int(a["price_cents"]) for a in addons)

    base_cents = int(svc["base_price_cents"] or 0)
    if svc["pricing_model"] == "deposit":
        charge_cents = int(svc["deposit_cents"] or 0) + addons_total
    elif svc["pricing_model"] == "full":
        charge_cents = base_cents + addons_total
    else:
        charge_cents = 0
    total_cents = base_cents + addons_total

    scheduled_date = data.get("scheduled_date") or None
    scheduled_start = data.get("scheduled_start") or None
    scheduled_end = data.get("scheduled_end") or None

    if svc["requires_calendar"] and (not scheduled_date or not scheduled_start):
        return jsonify({"error": "Please pick a date and time"}), 400

    booking_token = secrets.token_urlsafe(24)
    addon_snapshot = json.dumps([
        {"id": a["id"], "name": a["name"], "price_cents": int(a["price_cents"])}
        for a in addons
    ])

    pricing_model = svc["pricing_model"]
    if pricing_model == "rsvp":
        initial_status = "confirmed"
        payment_status = "none"
    elif pricing_model == "contract":
        initial_status = "pending"
        payment_status = "none"
    else:
        initial_status = "pending"
        payment_status = "pending"

    # Run the lookup, capacity check, and INSERT inside a single transaction
    # with SELECT ... FOR UPDATE on the parent service row, so two concurrent
    # bookings cannot both pass the capacity check and oversell the same slot.
    # Mirrors the pattern used in the events RSVP flow above.
    conn = get_db()
    conn.autocommit = False
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            # Lock the parent service row for the duration of this transaction.
            cur.execute(
                "SELECT id, capacity_per_slot, requires_calendar FROM services "
                "WHERE id = %s FOR UPDATE",
                (svc["id"],)
            )
            locked = cur.fetchone()
            if not locked:
                conn.rollback()
                return jsonify({"error": "Service not found"}), 404

            if locked["requires_calendar"]:
                cur.execute(
                    "SELECT COUNT(*) AS n FROM service_bookings "
                    "WHERE service_id = %s AND scheduled_date = %s "
                    "AND scheduled_start = %s "
                    "AND status IN ('pending','confirmed') "
                    "AND payment_status NOT IN ('expired','refunded')",
                    (svc["id"], scheduled_date, scheduled_start),
                )
                taken = (cur.fetchone() or {}).get("n", 0)
                cap = max(1, int(locked["capacity_per_slot"] or 1))
                if int(taken) >= cap:
                    conn.rollback()
                    return jsonify({"error": "Sorry, that slot just filled up. Please pick another."}), 409

            cur.execute(
                """INSERT INTO service_bookings
                   (service_id, booking_token, client_name, client_email, client_phone,
                    notes, scheduled_date, scheduled_start, scheduled_end,
                    selected_addon_ids, addon_snapshot, pricing_model,
                    base_price_cents, addons_total_cents, total_cents,
                    currency, payment_status, status,
                    utm_source, utm_medium, utm_campaign)
                   VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s::jsonb,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                   RETURNING *""",
                (
                    svc["id"], booking_token, name, email,
                    data.get("client_phone", ""),
                    data.get("notes", ""),
                    scheduled_date, scheduled_start, scheduled_end,
                    [a["id"] for a in addons],
                    addon_snapshot,
                    pricing_model,
                    base_cents, addons_total, total_cents,
                    (svc["currency"] or "usd").lower(),
                    payment_status, initial_status,
                    data.get("utm_source", ""),
                    data.get("utm_medium", ""),
                    data.get("utm_campaign", ""),
                ),
            )
            booking = cur.fetchone()
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.autocommit = True
    booking_dict = _service_to_dict(booking)

    # ----- Mirror this booking into the Forms tab so admins can track
    # all bookings + abandoned carts in one place. Best-effort —
    # never block the booking response if logging fails. ------------
    try:
        svc_dict = _service_to_dict(svc)
        form_id = _ensure_service_booking_form(svc_dict)
        if form_id:
            ua_string = request.headers.get("User-Agent", "")
            ip = (request.headers.get("X-Forwarded-For", request.remote_addr or "") or "").split(",")[0].strip()[:45]
            browser, os_name, device = _parse_ua(ua_string)
            session_id = (data.get("session_id") or "").strip()
            payload = _booking_submission_payload(svc_dict, booking_dict, data, addons)
            conf_number = booking_token[:20]

            existing_partial = None
            if session_id:
                existing_partial = query_db(
                    "SELECT id FROM form_submissions "
                    "WHERE form_id = %s AND session_id = %s AND status = 'partial' "
                    "ORDER BY submitted_at DESC LIMIT 1",
                    (form_id, session_id), fetchone=True,
                )

            if existing_partial:
                execute_db(
                    """UPDATE form_submissions SET
                         submission_data = %s::jsonb, status = 'new',
                         updated_at = NOW(), submitted_at = NOW(),
                         confirmation_number = %s,
                         device_type = %s, user_agent = %s,
                         referrer_url = %s, utm_source = %s, utm_medium = %s,
                         utm_campaign = %s, utm_term = %s, utm_content = %s,
                         page_url = %s, ip_address = %s, browser = %s, os = %s,
                         screen_resolution = %s, language = %s
                       WHERE id = %s""",
                    (
                        json.dumps(payload), conf_number,
                        device, ua_string[:500],
                        data.get("referrer", ""), data.get("utm_source", ""),
                        data.get("utm_medium", ""), data.get("utm_campaign", ""),
                        data.get("utm_term", ""), data.get("utm_content", ""),
                        data.get("page_url", ""), ip, browser, os_name,
                        data.get("screen_resolution", ""), data.get("language", ""),
                        existing_partial["id"],
                    ),
                )
            else:
                execute_db(
                    """INSERT INTO form_submissions
                        (form_id, submission_data, status, confirmation_number,
                         device_type, user_agent, referrer_url,
                         utm_source, utm_medium, utm_campaign, utm_term, utm_content,
                         page_url, ip_address, browser, os, screen_resolution,
                         language, session_id)
                       VALUES (%s, %s::jsonb, 'new', %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)""",
                    (
                        form_id, json.dumps(payload), conf_number,
                        device, ua_string[:500],
                        data.get("referrer", ""),
                        data.get("utm_source", ""), data.get("utm_medium", ""),
                        data.get("utm_campaign", ""), data.get("utm_term", ""),
                        data.get("utm_content", ""),
                        data.get("page_url", ""), ip, browser, os_name,
                        data.get("screen_resolution", ""), data.get("language", ""),
                        session_id,
                    ),
                )
    except Exception as _form_log_err:
        app.logger.warning("Service-booking form mirror failed: %s", _form_log_err)

    if pricing_model in ("deposit", "full"):
        if not stripe_client.is_configured():
            execute_db(
                "UPDATE service_bookings SET status = 'cancelled', "
                "payment_status = 'expired' WHERE id = %s",
                (booking["id"],),
            )
            return jsonify({
                "error": "Payments are not configured. Please contact us to book."
            }), 503
        try:
            stripe = stripe_client.get_stripe()
            label = svc["name"]
            if pricing_model == "deposit":
                label = f"Deposit — {svc['name']}"
            session = stripe.checkout.Session.create(
                mode="payment",
                payment_method_types=["card"],
                line_items=[{
                    "price_data": {
                        "currency": (svc["currency"] or "usd").lower(),
                        "unit_amount": charge_cents,
                        "product_data": {"name": label},
                    },
                    "quantity": 1,
                }],
                customer_email=email,
                success_url=request.host_url.rstrip("/")
                            + f"/booking/{booking_token}/success"
                            + "?session_id={CHECKOUT_SESSION_ID}",
                cancel_url=request.host_url.rstrip("/")
                           + f"/booking/{booking_token}/cancel",
                metadata={
                    "kind": "service_booking",
                    "booking_id": str(booking["id"]),
                    "booking_token": booking_token,
                    "service_id": str(svc["id"]),
                    "service_slug": svc["slug"],
                },
            )
            execute_db(
                "UPDATE service_bookings SET stripe_session_id = %s WHERE id = %s",
                (session.id, booking["id"]),
            )
            return jsonify({
                "status": "awaiting_payment",
                "booking_token": booking_token,
                "checkout_url": session.url,
            }), 201
        except Exception as e:
            execute_db(
                "UPDATE service_bookings SET status = 'cancelled', "
                "payment_status = 'expired' WHERE id = %s",
                (booking["id"],),
            )
            return jsonify({"error": f"Stripe error: {e}"}), 502

    # RSVP and contract: no payment, send confirmation now.
    _send_booking_confirmation(booking_dict, _service_to_dict(svc))
    # Include enough detail in the response that callers (the booking modal
    # AND the in-chat booking flow) can render a polished "you're booked"
    # summary panel — service name, scheduled date/time, add-ons, totals,
    # and the appropriate next-step link — without any extra round-trips.
    payload = {
        "status": "confirmed" if pricing_model == "rsvp" else "pending_contract",
        "booking_token": booking_token,
        "booking_id": booking["id"],
        "service_name": svc["name"],
        "service_slug": svc["slug"],
        "pricing_model": pricing_model,
        "client_name": name,
        "client_email": email,
        "scheduled_date": scheduled_date,
        "scheduled_start": scheduled_start,
        "scheduled_end": scheduled_end,
        "addons": [
            {"name": a["name"], "price_cents": int(a["price_cents"])}
            for a in addons
        ],
        "base_price_cents": base_cents,
        "addons_total_cents": addons_total,
        "total_cents": total_cents,
        "currency": (svc["currency"] or "usd").lower(),
        "success_url": f"/booking/{booking_token}/success",
    }
    if pricing_model == "contract":
        payload["contract_template_url"] = svc.get("contract_template_url") or ""
        # API endpoint clients POST the signed file to.
        payload["upload_url"] = f"/api/service-bookings/{booking_token}/contract"
        # User-facing page where the visitor actually picks the file —
        # safe to link to from a chat card or anchor tag.
        payload["contract_upload_page_url"] = f"/booking/{booking_token}/contract"
    return jsonify(payload), 201


# --------------- Public: client uploads signed contract ---------------

@app.route("/api/service-bookings/<string:token>/contract", methods=["POST"])
def api_upload_signed_contract(token):
    booking = query_db(
        "SELECT * FROM service_bookings WHERE booking_token = %s",
        (token,), fetchone=True,
    )
    if not booking:
        return jsonify({"error": "Booking not found"}), 404
    # Only contract-pricing bookings accept signed-contract uploads, and only
    # while still pending — otherwise an old token could overwrite a stored
    # file or re-trigger confirmation emails after the booking is settled.
    if booking.get("pricing_model") != "contract":
        return jsonify({"error": "This booking does not use a contract"}), 400
    if booking.get("status") not in ("pending",):
        return jsonify({
            "error": "This booking is no longer accepting contract uploads. "
                     "Contact us if you need to make a change."
        }), 409
    if "file" not in request.files:
        return jsonify({"error": "No file provided"}), 400
    f = request.files["file"]
    if not f.filename:
        return jsonify({"error": "No file selected"}), 400
    ext = f.filename.rsplit(".", 1)[-1].lower() if "." in f.filename else ""
    if ext not in ALLOWED_CONTRACT_EXTENSIONS:
        return jsonify({
            "error": f"File type .{ext} not allowed. Use pdf, doc, or docx."
        }), 400
    unique_name = f"signed_{booking['id']}_{secrets.token_hex(6)}.{ext}"
    storage.get_storage().write_fileobj(f"contracts/{unique_name}", f)
    url = f"/uploads/contracts/{unique_name}"
    row = execute_db(
        "UPDATE service_bookings SET signed_contract_url = %s, "
        "status = 'confirmed' WHERE id = %s RETURNING *",
        (url, booking["id"]),
    )
    svc = query_db("SELECT * FROM services WHERE id = %s",
                   (booking["service_id"],), fetchone=True)
    _send_booking_confirmation(_service_to_dict(row), _service_to_dict(svc))
    return jsonify({"success": True, "signed_contract_url": url})


# --------------- Stripe webhook handlers (wired in below) ---------------

def _handle_service_booking_checkout_completed(session_obj):
    metadata = session_obj.get("metadata") or {}
    if metadata.get("kind") != "service_booking":
        return
    booking_id = metadata.get("booking_id")
    session_id = session_obj.get("id")
    amount_total = session_obj.get("amount_total")
    if not booking_id:
        return
    conn = get_db()
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute(
                "SELECT id, payment_status FROM service_bookings "
                "WHERE id = %s FOR UPDATE",
                (booking_id,),
            )
            row = cur.fetchone()
            if not row or row["payment_status"] == "paid":
                conn.commit()
                return
            cur.execute(
                """UPDATE service_bookings
                   SET payment_status = 'paid',
                       status = 'confirmed',
                       amount_paid_cents = COALESCE(%s, amount_paid_cents),
                       stripe_session_id = COALESCE(stripe_session_id, %s)
                   WHERE id = %s
                   RETURNING *""",
                (amount_total, session_id, booking_id),
            )
            booking = cur.fetchone()
            cur.execute(
                "SELECT * FROM services WHERE id = %s",
                (booking["service_id"],),
            )
            svc = cur.fetchone()
            conn.commit()
    finally:
        conn.close()
    _send_booking_confirmation(_service_to_dict(booking), _service_to_dict(svc))


def _handle_service_booking_checkout_expired(session_obj):
    metadata = session_obj.get("metadata") or {}
    if metadata.get("kind") != "service_booking":
        return
    booking_id = metadata.get("booking_id")
    if not booking_id:
        return
    execute_db(
        "UPDATE service_bookings "
        "SET payment_status = 'expired', status = 'cancelled' "
        "WHERE id = %s AND payment_status = 'pending'",
        (booking_id,),
    )


