# ----- Widget execution ----------------------------------------------------

@app.route("/admin/api/dashboards/widgets/<int:wid>/run", methods=["POST"])
@admin_required
def admin_run_widget(wid):
    """Execute the widget's data source and return rendered data."""
    row = query_db(
        "SELECT id, name, widget_type, source_type, source_config "
        "FROM dashboard_widgets WHERE id = %s",
        (wid,), fetchone=True,
    )
    if not row:
        return jsonify({"error": "Widget not found"}), 404
    cfg = row.get("source_config") or {}
    try:
        if row["source_type"] == "builtin":
            metric_key = cfg.get("metric")
            if metric_key not in BUILTIN_METRICS:
                return jsonify({"error": "Unknown built-in metric."}), 400
            fn = BUILTIN_METRICS[metric_key][0]
            data = fn(cfg)
        elif row["source_type"] == "internal_db":
            data = _run_internal_db(row["widget_type"], cfg)
        elif row["source_type"] == "external_postgres":
            conn_id = cfg.get("connection_id")
            query = cfg.get("query", "")
            if not conn_id or not query:
                return jsonify({"error": "Connection and query are required."}), 400
            conn_row = query_db(
                "SELECT encrypted_config FROM external_data_connections "
                "WHERE id = %s AND kind = 'postgres'",
                (conn_id,), fetchone=True,
            )
            if not conn_row:
                return jsonify({"error": "Connection not found."}), 404
            url = decrypt_secret(conn_row["encrypted_config"])
            raw = _run_external_postgres(url, query)
            data = _shape_external_data_for_widget(raw, row["widget_type"], cfg)
        elif row["source_type"] == "external_rest":
            conn_id = cfg.get("connection_id")
            if not conn_id:
                return jsonify({"error": "Connection is required."}), 400
            conn_row = query_db(
                "SELECT encrypted_config FROM external_data_connections "
                "WHERE id = %s AND kind = 'rest'",
                (conn_id,), fetchone=True,
            )
            if not conn_row:
                return jsonify({"error": "Connection not found."}), 404
            base_cfg = json.loads(decrypt_secret(conn_row["encrypted_config"]) or "{}")
            data = _run_external_rest(base_cfg, cfg)
        else:
            return jsonify({"error": "Unknown source type."}), 400
        return jsonify({
            "widget_type": row["widget_type"],
            "name": row["name"],
            "data": data,
        })
    except Exception as e:
        app.logger.exception("widget run failed (id=%s): %s", wid, e)
        return jsonify({"error": str(e)[:240]}), 400


def _shape_external_data_for_widget(raw, widget_type, cfg):
    """Convert a {columns, rows} table result into the shape a given widget
    type expects. KPI takes the first cell; line/bar use first column as
    labels and second as numeric values."""
    cols = raw.get("columns") or []
    rows = raw.get("rows") or []
    if widget_type == "kpi":
        if not rows or not rows[0]:
            return {"value": 0, "label": cfg.get("label") or "Value"}
        return {
            "value": rows[0][0],
            "label": cfg.get("label") or (cols[0] if cols else "Value"),
        }
    if widget_type in ("line", "bar"):
        if len(cols) < 2:
            raise ValueError("Chart needs at least 2 columns (label, value).")
        labels = [str(r[0]) if r else "" for r in rows]
        values = []
        for r in rows:
            try:
                values.append(float(r[1]) if len(r) > 1 and r[1] is not None else 0)
            except (TypeError, ValueError):
                values.append(0)
        return {"labels": labels, "values": values}
    # table
    return {"columns": cols, "rows": rows}


# =============================================================================
# MESSAGING — admin API + webhooks + unsubscribe + scheduler
# =============================================================================
# Email + SMS messaging layer. Admin UI lives under "Messaging" in the
# sidebar. Public webhooks (no auth) come from Resend / Twilio. Public
# unsubscribe link is signed so subscribers cannot opt each other out.

def _email_re_check(addr: str) -> bool:
    if not addr:
        return False
    return bool(re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", addr.strip()))


def _public_base_url() -> str:
    """Best-effort canonical URL for unsubscribe / webhook links."""
    settings = query_db("SELECT seo_canonical_url FROM site_settings WHERE id = 1", fetchone=True)
    if settings and (settings.get("seo_canonical_url") or "").strip():
        return settings["seo_canonical_url"].rstrip("/")
    # Explicit PUBLIC_BASE_URL wins (works on any host).
    explicit = (os.environ.get("PUBLIC_BASE_URL") or "").strip().rstrip("/")
    if explicit:
        return explicit
    # Replit-managed hostname fallback for Replit-hosted installs.
    domains = (os.environ.get("REPLIT_DOMAINS") or "").strip()
    if domains:
        first = domains.split(",")[0].strip()
        if first:
            return f"https://{first}"
    return request.host_url.rstrip("/") if request else ""


def _unsub_url(subscriber_id: int) -> str:
    base = _public_base_url() or ""
    token = messaging.make_unsubscribe_token(subscriber_id)
    return f"{base}/unsubscribe?token={token}"


def _wrap_email_html(html_body: str, subscriber_id: int) -> str:
    """Inject a footer with the unsubscribe link if the body does not
    already include one. Keeps templates simple — admins don't have to
    remember to paste an unsubscribe footer into every template."""
    body = html_body or ""
    if "{{unsubscribe_url}}" in body:
        # Body already has its own unsubscribe placeholder — caller will
        # have rendered the merge tag with the real URL.
        return body
    if 'href="' in body and ("unsubscribe" in body.lower() or "/unsubscribe?" in body):
        return body
    unsub = _unsub_url(subscriber_id)
    footer = (
        '<hr style="border:none;border-top:1px solid #e5e7eb;margin:2rem 0 1rem 0">'
        '<p style="font-size:12px;color:#6b7280;text-align:center;font-family:Arial,sans-serif">'
        f'You\'re receiving this because you subscribed. '
        f'<a href="{html_module.escape(unsub, quote=True)}" '
        'style="color:#6b7280;text-decoration:underline">Unsubscribe</a>.'
        "</p>"
    )
    return body + footer


def _row_subscriber(row):
    if not row:
        return None
    cf = row.get("custom_fields") or {}
    return {
        "id": row["id"],
        "email": row["email"],
        "phone": row["phone"],
        "full_name": row["full_name"],
        "list_name": row["list_name"],
        "source": row["source"],
        "opt_in": row["opt_in"],
        "opt_in_email": row.get("opt_in_email", True),
        "opt_in_sms": row.get("opt_in_sms", True),
        "custom_fields": cf if isinstance(cf, dict) else {},
        "unsubscribed_at": row["unsubscribed_at"].isoformat() if row.get("unsubscribed_at") else None,
        "created_at": row["created_at"].isoformat() if row.get("created_at") else None,
    }


# --- subscriber resolution for campaigns -------------------------------------

def _resolve_recipients(channel: str, recipient_kind: str, recipient_filter: dict):
    """Return a list of subscriber rows that match the campaign's targeting.
    Respects opt_in / opt_in_email / opt_in_sms and skips rows missing the
    required address column for the channel."""
    where = ["opt_in = TRUE"]
    params = []
    if channel == "email":
        where.append("email <> ''")
        where.append("opt_in_email = TRUE")
    elif channel == "sms":
        where.append("phone <> ''")
        where.append("opt_in_sms = TRUE")
    if recipient_kind == "list":
        list_name = (recipient_filter or {}).get("list_name") or "default"
        where.append("list_name = %s")
        params.append(list_name)
    elif recipient_kind == "ids":
        ids = (recipient_filter or {}).get("ids") or []
        ids = [int(i) for i in ids if str(i).strip().lstrip("-").isdigit()]
        if not ids:
            return []
        placeholders = ",".join(["%s"] * len(ids))
        where.append(f"id IN ({placeholders})")
        params.extend(ids)
    sql = f"SELECT * FROM subscribers WHERE {' AND '.join(where)} ORDER BY id"
    rows = query_db(sql, tuple(params))
    return rows or []


# --- send-one helper used by both test send and campaign dispatcher ---------

def _send_one(template_or_snapshot: dict, subscriber: dict, *, campaign_id=None,
              is_test=False) -> dict:
    """Render a template against one subscriber and send it. Writes a
    messaging_log row in any outcome (success or failure) and returns it.
    `template_or_snapshot` accepts either a real template row or a dict
    with channel/subject/body/from_name/reply_to so campaigns can pass
    their snapshot."""
    channel = template_or_snapshot.get("channel") or "email"
    subject_tpl = template_or_snapshot.get("subject") or ""
    body_tpl = template_or_snapshot.get("body") or ""
    reply_to = (template_or_snapshot.get("reply_to") or "").strip() or None
    from_name = (template_or_snapshot.get("from_name") or "").strip()

    sub_id = subscriber.get("id") or 0
    ctx = messaging.subscriber_context(subscriber, extra={
        "unsubscribe_url": _unsub_url(sub_id) if sub_id else "",
    })

    rendered_subject = messaging.render_merge_tags(subject_tpl, ctx)
    rendered_body = messaging.render_merge_tags(body_tpl, ctx)

    to_address = subscriber.get("email", "") if channel == "email" else subscriber.get("phone", "")
    log_row = execute_db(
        """
        INSERT INTO messaging_log
            (campaign_id, subscriber_id, channel, to_address,
             subject_snapshot, body_snapshot, status, provider, is_test)
        VALUES (%s, %s, %s, %s, %s, %s, 'queued', %s, %s)
        RETURNING *
        """,
        (
            campaign_id,
            sub_id or None,
            channel,
            to_address,
            rendered_subject,
            rendered_body,
            "resend" if channel == "email" else "twilio",
            bool(is_test),
        ),
    )
    log_id = log_row["id"]

    try:
        if channel == "email":
            sender_override = None
            if from_name:
                # Resend accepts "Name <addr@example.com>" syntax.
                _, default_from = messaging._resolve_resend()
                if default_from and "<" not in default_from:
                    sender_override = f"{from_name} <{default_from}>"
            html_body = _wrap_email_html(rendered_body, sub_id)
            resp = messaging.send_email(
                to_address,
                rendered_subject,
                html_body,
                from_override=sender_override,
                reply_to=reply_to,
                tags=[("campaign_id", str(campaign_id or 0)), ("log_id", str(log_id))],
                headers={
                    "List-Unsubscribe": f"<{_unsub_url(sub_id)}>" if sub_id else "",
                    "List-Unsubscribe-Post": "List-Unsubscribe=One-Click",
                } if sub_id else None,
            )
            provider_id = resp.get("id") or ""
        else:
            # Cap gate before paying Twilio. Background-job variant so we
            # short-circuit cleanly instead of returning a Flask response.
            if cost_cap_blocks_send("sms_campaign"):
                execute_db(
                    "UPDATE messaging_log SET status='failed', "
                    "  error_text='AI spend cap reached — send skipped' "
                    " WHERE id=%s",
                    (log_id,),
                )
                return {"ok": False, "log_id": log_id,
                        "error": "cap_reached"}
            # Ask Twilio to POST status updates to our webhook so the per-
            # recipient log gets delivered/failed updates without the admin
            # needing to wire StatusCallback in the Twilio console.
            try:
                status_cb = url_for("webhook_twilio_status", _external=True)
            except Exception:
                status_cb = None
            resp = messaging.send_sms(
                to_address, rendered_body, status_callback_url=status_cb,
            )
            provider_id = resp.get("sid") or ""
            # Pass through Twilio's reported segment count exactly. If
            # it's missing or unparseable we pass None so the ledger row
            # records segments=NULL / cost=NULL — never fabricate "1".
            raw_segs = resp.get("num_segments")
            segs = None
            if raw_segs is not None:
                try:
                    segs = int(raw_segs)
                except (TypeError, ValueError):
                    segs = None
            record_sms_cost(
                surface="sms_campaign",
                to_number=to_address,
                message_sid=provider_id,
                segments=segs,
            )
        execute_db(
            """
            UPDATE messaging_log
               SET status = 'sent',
                   provider_message_id = %s,
                   sent_at = NOW()
             WHERE id = %s
            """,
            (provider_id, log_id),
        )
        return {"ok": True, "log_id": log_id, "provider_message_id": provider_id}
    except messaging.MessagingError as e:
        execute_db(
            "UPDATE messaging_log SET status='failed', error_text=%s WHERE id=%s",
            (str(e)[:500], log_id),
        )
        return {"ok": False, "log_id": log_id, "error": str(e)}
    except Exception as e:
        execute_db(
            "UPDATE messaging_log SET status='failed', error_text=%s WHERE id=%s",
            (f"unexpected: {e}"[:500], log_id),
        )
        return {"ok": False, "log_id": log_id, "error": str(e)}


# --- background dispatcher ---------------------------------------------------

def _dispatch_due_campaigns():
    """Pick up any campaigns whose send_at has passed and dispatch them.
    Atomically claims each campaign by transitioning queued → sending so
    overlapping ticks (or two scheduler copies in dev) cannot double-send."""
    rows = query_db(
        """
        SELECT id FROM messaging_campaigns
         WHERE status = 'queued' AND (send_at IS NULL OR send_at <= NOW())
         ORDER BY id
         LIMIT 25
        """
    ) or []
    for row in rows:
        cid = row["id"]
        # Atomic claim: only one tick will succeed for a given campaign.
        claimed = execute_db(
            """
            UPDATE messaging_campaigns
               SET status='sending', started_at=NOW()
             WHERE id=%s AND status='queued'
            RETURNING *
            """,
            (cid,),
        )
        if not claimed:
            continue
        try:
            _send_campaign(claimed)
        except Exception as e:  # never let one campaign kill the loop
            execute_db(
                """
                UPDATE messaging_campaigns
                   SET status='failed',
                       finished_at=NOW(),
                       error_text=%s
                 WHERE id=%s
                """,
                (str(e)[:500], cid),
            )


def _send_campaign(campaign: dict):
    snapshot = {
        "channel": campaign["channel"],
        "subject": campaign["subject_snapshot"],
        "body": campaign["body_snapshot"],
    }
    recipients = _resolve_recipients(
        campaign["channel"],
        campaign["recipient_kind"],
        campaign.get("recipient_filter") or {},
    )
    sent = 0
    failed = 0
    for sub in recipients:
        outcome = _send_one(snapshot, sub, campaign_id=campaign["id"])
        if outcome.get("ok"):
            sent += 1
        else:
            failed += 1
    execute_db(
        """
        UPDATE messaging_campaigns
           SET status = CASE
                          WHEN %s > 0 AND %s = 0 THEN 'failed'
                          ELSE 'sent'
                        END,
               finished_at = NOW(),
               total_recipients = %s,
               sent_count = %s,
               failed_count = %s
         WHERE id = %s
        """,
        (failed, sent, len(recipients), sent, failed, campaign["id"]),
    )


messaging.register_tick(_dispatch_due_campaigns)


# =============================================================================
# AUTOMATIONS — wire the engine module to app-level helpers
# =============================================================================
# automations.py intentionally has no `from app import …` so we hand it the
# few things it needs (DB helpers, OpenAI client, schema introspection,
# messaging) at import time. We also register its scheduler tick onto
# messaging's existing 30s loop instead of starting a second thread.
automations.configure(
    query_db=query_db,
    execute_db=execute_db,
    database_url=DATABASE_URL,
    openai_client=openai_client,
    public_base_url_fn=_public_base_url if "_public_base_url" in globals() else (lambda: ""),
    schema_introspect_fn=_internal_db_schema,
    table_blocklist=_INTERNAL_DB_TABLE_BLOCKLIST,
    qident_fn=_qident,
    messaging_module=messaging,
    # Phase 2 hooks so automation-triggered SMS sends respect the
    # tenant cost cap and write a ledger row exactly like the
    # in-process SMS call sites do.
    cost_cap_blocks_send_fn=cost_cap_blocks_send,
    record_sms_cost_fn=record_sms_cost,
)
automations.register_with_scheduler(messaging)


def _automations_call_skill_hook(skill_name, args_dict):
    """Bridge from the automations engine's `call_skill` action into the
    chat-tool dispatcher.

    Lets every enabled chat skill — built-ins, custom webhooks, custom
    SQL, knowledge, AND every MCP tool — be used as an automation step
    without adding a new action kind per skill. New skills become
    selectable as soon as they appear (and are enabled) in the
    `agent_skills` table.

    Returns a dict shaped {ok, result, error} that the engine forwards
    into the run log.
    """
    try:
        result_str, _log_entry = _execute_chat_tool_inner(
            skill_name, json.dumps(args_dict or {}, default=str)
        )
    except Exception as e:
        return {"ok": False, "error": f"Dispatcher crashed: {e}"}
    try:
        parsed = json.loads(result_str) if result_str else None
    except Exception:
        # Skill returned non-JSON for some reason — still surface it as
        # the result string so the run log is informative.
        return {"ok": True, "result": result_str}
    if isinstance(parsed, dict) and "error" in parsed and len(parsed) == 1:
        # Dispatcher's well-known error envelope: {"error": "..."}.
        return {"ok": False, "error": str(parsed.get("error") or "Skill failed.")}
    return {"ok": True, "result": parsed}


automations.set_skill_executor(_automations_call_skill_hook)


# =============================================================================
# AUTOMATIONS — admin CRUD + run log + public webhook
# =============================================================================
# All admin endpoints live under /admin/api/automations. The public webhook
# is /automations/hook/<token> and it only fires automations whose
# webhook_token matches AND whose enabled flag is TRUE.

def _row_automation(r):
    """Coerce a DB row into the JSON shape the admin UI expects."""
    if not r:
        return None
    return {
        "id": r["id"],
        "name": r.get("name") or "",
        "description": r.get("description") or "",
        "enabled": bool(r.get("enabled")),
        "trigger_type": r.get("trigger_type") or "manual",
        "trigger_config": r.get("trigger_config") or {},
        "action_steps": r.get("action_steps") or [],
        "webhook_token": r.get("webhook_token") or "",
        "last_run_at": r.get("last_run_at").isoformat() if r.get("last_run_at") else None,
        "last_run_status": r.get("last_run_status") or "",
        "next_scheduled_at": r.get("next_scheduled_at").isoformat() if r.get("next_scheduled_at") else None,
        "created_at": r.get("created_at").isoformat() if r.get("created_at") else None,
        "updated_at": r.get("updated_at").isoformat() if r.get("updated_at") else None,
    }


# Keys inside trigger_config that are sensitive enough that the editor
# should never see them in cleartext. The full value stays in the DB row
# (and so verify_webhook_signature() keeps working as before) — only the
# JSON sent back to the browser is masked. Add new keys here as more
# trigger types start collecting credentials.
_AUTOMATION_REDACTED_TRIGGER_KEYS = ("signature_secret",)


def _mask_signature_secret(secret):
    """Return a short, safe preview of a secret like ``whsec_••••abcd``.

    Keeps a recognizable prefix (e.g. ``whsec_``) when the secret has
    one in the first dozen characters, plus the last 4 characters so an
    admin can spot which key is saved without learning anything useful
    if the response leaks. Empty input returns empty so callers don't
    have to special-case "no secret saved yet"."""
    if not isinstance(secret, str):
        return ""
    s = secret.strip()
    if not s:
        return ""
    if len(s) <= 4:
        return "••••"
    last4 = s[-4:]
    underscore = s.find("_")
    prefix = s[: underscore + 1] if 0 < underscore <= 12 else ""
    return f"{prefix}••••{last4}"


def _redact_automation_for_editor(automation):
    """Return a shallow copy of an automation dict with sensitive
    trigger_config values replaced by a masked preview.

    The standard pattern (Stripe / GitHub) is to show only a short
    fingerprint of a stored secret after save and require the admin to
    re-paste to change it. Anything that lands in the browser response
    is reachable via DevTools or a stolen session cookie, so the
    cleartext secret must never leave the server here. The verifier
    still loads the full secret from the DB row directly."""
    if not automation:
        return automation
    cfg = automation.get("trigger_config") or {}
    if not isinstance(cfg, dict):
        return automation
    masked_cfg = None
    for key in _AUTOMATION_REDACTED_TRIGGER_KEYS:
        val = cfg.get(key)
        if isinstance(val, str) and val:
            if masked_cfg is None:
                masked_cfg = dict(cfg)
            masked_cfg[key] = _mask_signature_secret(val)
    if masked_cfg is None:
        return automation
    out = dict(automation)
    out["trigger_config"] = masked_cfg
    return out


def _merge_preserved_trigger_secrets(new_cfg, existing_cfg):
    """Mutate ``new_cfg`` in place so that any redacted trigger_config
    secret the editor *didn't* actually re-enter falls back to the
    cleartext value still on disk.

    The editor renders the password input empty (with the masked
    preview shown alongside) so a vanilla save with no edits sends back
    an empty string — that's the "leave unchanged" signal. We also
    treat the masked preview itself as unchanged in case a script or
    integration round-trips the GET response straight into a PUT."""
    if not isinstance(new_cfg, dict) or not isinstance(existing_cfg, dict):
        return
    for key in _AUTOMATION_REDACTED_TRIGGER_KEYS:
        existing_val = existing_cfg.get(key)
        if not isinstance(existing_val, str) or not existing_val:
            continue
        new_val = new_cfg.get(key, "")
        if not isinstance(new_val, str):
            new_val = ""
        if not new_val.strip() or new_val == _mask_signature_secret(existing_val):
            new_cfg[key] = existing_val


def _row_run(r):
    if not r:
        return None
    return {
        "id": r["id"],
        "automation_id": r.get("automation_id"),
        "status": r.get("status") or "",
        "triggered_by": r.get("triggered_by") or "",
        "trigger_data": r.get("trigger_data") or {},
        "step_results": r.get("step_results") or [],
        "error_text": r.get("error_text") or "",
        "is_dry_run": bool(r.get("is_dry_run")),
        "queued_at": r.get("queued_at").isoformat() if r.get("queued_at") else None,
        "started_at": r.get("started_at").isoformat() if r.get("started_at") else None,
        "finished_at": r.get("finished_at").isoformat() if r.get("finished_at") else None,
    }


_AUTOMATION_TRIGGER_KINDS = {t["kind"] for t in automations.TRIGGER_TYPES}
_AUTOMATION_ACTION_KINDS = {a["kind"] for a in automations.ACTION_TYPES}


# Hard caps for the rule tree on a single `when` filter or condition
# action's config. These prevent a malicious or runaway editor from
# saving a tree large enough to choke the evaluator or the JSONB row.
_RULE_MAX_DEPTH = 5
_RULE_MAX_LEAVES = 50


def _clean_rule_tree(node, path, valid_operators, depth=0, counter=None):
    """Recursively clean a rule tree (used by both the per-step `when`
    filter and the standalone condition action's config).

    Accepts either a leaf `{field, operator, value}` or a group
    `{combinator: AND|OR, rules: [<node>, ...]}` with arbitrarily
    nested sub-groups. Empty leaves (no field + non-unary operator)
    are dropped; an entirely-empty tree returns None so the caller
    can skip persisting it.

    Raises ValueError on shape problems, unknown operators/combinators,
    or if the tree exceeds the depth/leaf-count caps."""
    if counter is None:
        counter = [0]
    if depth > _RULE_MAX_DEPTH:
        raise ValueError(f"{path}: rule nesting too deep (max {_RULE_MAX_DEPTH}).")
    if not isinstance(node, dict):
        raise ValueError(f"{path}: rule must be an object.")
    # Treat anything with a `rules` key OR an explicit `combinator` as a
    # group; that way a group can be empty (rules: []) and still be
    # recognized correctly.
    is_group = isinstance(node.get("rules"), list) or "combinator" in node
    if is_group:
        combinator_in = node.get("combinator")
        if combinator_in is None:
            combinator = "AND"
        elif isinstance(combinator_in, str):
            combinator = combinator_in.strip().upper() or "AND"
        else:
            raise ValueError(f"{path}: combinator must be a string.")
        if combinator not in ("AND", "OR"):
            raise ValueError(
                f"{path}: combinator must be AND or OR (got {combinator_in!r})."
            )
        rules_in = node.get("rules") or []
        if not isinstance(rules_in, list):
            raise ValueError(f"{path}.rules must be a list.")
        cleaned_rules = []
        for j, r in enumerate(rules_in):
            cleaned = _clean_rule_tree(
                r, f"{path}.rules[{j}]", valid_operators, depth + 1, counter,
            )
            if cleaned is not None:
                cleaned_rules.append(cleaned)
        if not cleaned_rules:
            return None
        return {"combinator": combinator, "rules": cleaned_rules}
    # Leaf node.
    counter[0] += 1
    if counter[0] > _RULE_MAX_LEAVES:
        raise ValueError(f"too many rules (max {_RULE_MAX_LEAVES}).")
    op_in = node.get("operator")
    if op_in is None:
        op = "eq"
    elif isinstance(op_in, str):
        op = op_in.strip().lower() or "eq"
    else:
        raise ValueError(f"{path}: operator must be a string.")
    if op not in valid_operators:
        raise ValueError(f"{path}: unknown operator: {op_in!r}")
    field = node.get("field")
    field_str = field.strip() if isinstance(field, str) else ""
    value = node.get("value")
    if not isinstance(value, str):
        value = "" if value is None else str(value)
    if not field_str and op not in ("blank", "not_blank"):
        # Empty rule — drop it so half-built filters don't pollute the
        # saved row.
        return None
    return {"field": field_str, "operator": op, "value": value}


def _validate_automation_payload(data):
    """Raise ValueError if the inbound payload from the editor is malformed."""
    if not isinstance(data, dict):
        raise ValueError("Body must be a JSON object.")
    name = (data.get("name") or "").strip()
    if not name:
        raise ValueError("Name is required.")
    trigger_type = (data.get("trigger_type") or "").strip()
    if trigger_type not in _AUTOMATION_TRIGGER_KINDS:
        raise ValueError(f"Unknown trigger type: {trigger_type!r}")
    trigger_config = data.get("trigger_config") or {}
    if not isinstance(trigger_config, dict):
        raise ValueError("trigger_config must be an object.")
    steps = data.get("action_steps") or []
    if not isinstance(steps, list):
        raise ValueError("action_steps must be a list.")
    cleaned_steps = []
    valid_operators = {o["value"] for o in automations.CONDITION_OPERATORS}
    for i, s in enumerate(steps, start=1):
        if not isinstance(s, dict):
            raise ValueError(f"Step {i} must be an object.")
        kind = (s.get("kind") or "").strip()
        if kind not in _AUTOMATION_ACTION_KINDS:
            raise ValueError(f"Step {i} has unknown action kind: {kind!r}")
        cfg = s.get("config") or {}
        if not isinstance(cfg, dict):
            raise ValueError(f"Step {i} config must be an object.")
        # The standalone condition action's config IS a rule tree, so
        # validate it through the same cleaner. Other actions store
        # their fields freely under config and we leave the dict alone.
        if kind == "condition":
            cleaned_cfg = _clean_rule_tree(
                cfg, f"step {i} condition", valid_operators,
            )
            if cleaned_cfg is None:
                raise ValueError(
                    f"Step {i}: condition needs at least one rule with a non-empty field."
                )
            cfg = cleaned_cfg
        cleaned_step = {
            "kind": kind,
            "name": (s.get("name") or "").strip(),
            "config": cfg,
        }
        # Optional per-step "Only run when…" filter. Accepts either a
        # legacy leaf `{field, operator, value}` or a `{combinator,
        # rules}` group with arbitrarily nested AND/OR sub-groups. Only
        # persisted when the admin actually entered at least one rule
        # with a non-empty field (or chose a unary operator like "is
        # blank") so empty filters don't pollute the saved row.
        when_raw = s.get("when")
        if isinstance(when_raw, dict):
            cleaned_when = _clean_rule_tree(
                when_raw, f"step {i} 'when' filter", valid_operators,
            )
            if cleaned_when is not None:
                cleaned_step["when"] = cleaned_when
        cleaned_steps.append(cleaned_step)
    # Every save path (direct CRUD, restore, import, test-run, AI
    # propose/approve) flows through this validator, so the call_skill
    # skill-name guard belongs here rather than only in the AI propose
    # helper. Otherwise the editor or a raw API call could persist a
    # call_skill step whose `skill_name` doesn't resolve to an enabled
    # `agent_skills` row, and the failure would only surface at runtime
    # when the automation actually fires.
    skill_err = _admin_validate_automation_call_skill_steps(cleaned_steps)
    if skill_err:
        raise ValueError(skill_err)
    return {
        "name": name,
        "description": (data.get("description") or "").strip(),
        "enabled": bool(data.get("enabled")),
        "trigger_type": trigger_type,
        "trigger_config": trigger_config,
        "action_steps": cleaned_steps,
    }


def _automations_skill_catalogue():
    """Build the list of every skill (chat-tool) the `call_skill` action
    can invoke, in the shape the editor's progressive-disclosure picker
    needs.

    Each entry has:
        name          — agent_skills.name, the value passed to call_skill
        display_name  — friendly label (admin-edited if any, else fallback)
        description   — short blurb shown under the name
        category      — admin-set bucket from agent_skills.category
        source        — origin tag for the picker grouping:
                            'builtin' | 'mcp' | 'webhook' | 'sql' | 'knowledge' | 'custom'
        server_name   — MCP server label, only when source == 'mcp'
        args_schema   — JSON schema dict for the skill's arguments, so the
                        UI can render a friendly form (or fall back to a
                        JSON textarea).

    We use audience='admin' so MCP servers gated to admin-only are
    visible here even when they're hidden from the visitor agent. New
    rows in agent_skills are picked up automatically — that's the whole
    point of routing through the existing dispatcher.
    """
    try:
        rows = query_db(
            "SELECT name, display_name, description, category, builtin, "
            "config_json FROM agent_skills WHERE enabled = true "
            "ORDER BY display_name, name"
        ) or []
    except Exception as e:
        print(f"[automations] skill catalogue load failed: {e}")
        return []

    # Pre-load MCP server visibility + display names in one query so we
    # don't hit the DB once per row inside the loop.
    mcp_meta = {}
    if any((_custom_skill_cfg(r).get("type") or "").lower() == "mcp"
           for r in rows if not r.get("builtin")):
        try:
            srvs = query_db(
                "SELECT id, name, allowed_for_admin FROM mcp_servers"
            ) or []
            for s in srvs:
                mcp_meta[int(s["id"])] = {
                    "admin_allowed": bool(s.get("allowed_for_admin")),
                    "server_name":   s.get("name") or "",
                }
        except Exception:
            pass

    builtin_schemas = {
        (t.get("function") or {}).get("name"): (t.get("function") or {}).get("parameters", {})
        for t in CHAT_TOOLS
    }

    out = []
    for r in rows:
        name = r["name"]
        is_builtin = bool(r.get("builtin"))
        cfg = _custom_skill_cfg(r)
        skill_type = (cfg.get("type") or "").strip().lower()

        if is_builtin:
            source = "builtin"
        elif skill_type == "mcp":
            source = "mcp"
        elif skill_type == "webhook":
            source = "webhook"
        elif skill_type == "sql":
            source = "sql"
        elif skill_type == "knowledge" or name == _KNOWLEDGE_LOOKUP_SKILL_NAME:
            source = "knowledge"
        else:
            source = "custom"

        server_name = ""
        if source == "mcp":
            srv_id = cfg.get("server_id")
            try:
                vis = mcp_meta.get(int(srv_id) if srv_id is not None else -1) or {}
            except (TypeError, ValueError):
                vis = {}
            # Hide MCP tools whose server isn't allowed for admin so the
            # picker doesn't list something the dispatcher would refuse.
            if not vis.get("admin_allowed"):
                continue
            server_name = vis.get("server_name") or ""

        if is_builtin:
            args_schema = builtin_schemas.get(name) or {
                "type": "object", "properties": {}, "required": [],
            }
        else:
            try:
                args_schema = _custom_skill_args_schema(name, cfg)
            except Exception:
                args_schema = {"type": "object", "properties": {}, "required": []}

        display_name = (r.get("display_name") or "").strip() or name.replace("_", " ").title()
        description = (r.get("description") or "").strip()
        category = (r.get("category") or "lookup").strip() or "lookup"

        out.append({
            "name": name,
            "display_name": display_name,
            "description": description,
            "category": category,
            "source": source,
            "server_name": server_name,
            "args_schema": args_schema,
        })
    return out


@app.route("/admin/api/automations/metadata")
@admin_required
def admin_automations_metadata():
    """Return the trigger + action catalogues plus the available DB tables,
    active forms, and the live skill catalogue — everything the editor
    UI needs to render its pickers (including the progressive-disclosure
    "Use a skill" picker for the call_skill action)."""
    forms = query_db(
        "SELECT id, name, slug FROM custom_forms WHERE status = 'active' ORDER BY name"
    ) or []
    return jsonify({
        "triggers": automations.trigger_metadata(),
        "actions": automations.action_metadata(),
        "condition_operators": automations.condition_operator_metadata(),
        "tables": _internal_db_schema(),
        "forms": [{"id": f["id"], "name": f["name"], "slug": f["slug"]} for f in forms],
        "limits": automations.status_summary(),
        "public_base_url": _public_base_url(),
        "skills": _automations_skill_catalogue(),
    })


@app.route("/admin/api/automations/settings", methods=["GET"])
@admin_required
def admin_automations_settings_get():
    """Return the run-history retention knobs in the shape the editor needs:
    the *effective* values (DB override or env-var fallback), the env-var
    defaults so the form can show a "default: N" hint next to each input,
    and whether the current value is a DB override or the default. The
    `automation_settings` row is seeded by `init_db` so it always exists."""
    row = query_db(
        "SELECT retention_days, keep_recent_per_automation, updated_at "
        "FROM automation_settings WHERE id = 1",
        fetchone=True,
    )
    if not row:
        # Defensive seed in case the row was manually deleted — keeps this
        # endpoint idempotent.
        execute_db(
            "INSERT INTO automation_settings (id) VALUES (1) "
            "ON CONFLICT (id) DO NOTHING"
        )
        row = query_db(
            "SELECT retention_days, keep_recent_per_automation, updated_at "
            "FROM automation_settings WHERE id = 1",
            fetchone=True,
        ) or {}
    return jsonify({
        "retention_days": row.get("retention_days"),
        "keep_recent_per_automation": row.get("keep_recent_per_automation"),
        "updated_at": row["updated_at"].isoformat() if row.get("updated_at") else None,
        "effective": automations.retention_settings(),
    })


@app.route("/admin/api/automations/settings", methods=["PUT"])
@admin_required
def admin_automations_settings_put():
    """Save (or clear) the admin-tunable retention knobs. Each field is
    optional: omitted or explicitly null means "remove the override and
    fall back to the env-var default". We clamp into the same bounds the
    cleanup tick enforces so a typo can't disable retention entirely or
    blow up the cleanup query with a nonsense interval."""
    body = request.get_json(silent=True) or {}
    if not isinstance(body, dict):
        return jsonify({"error": "Body must be a JSON object."}), 400

    def _opt_clamped_int(key, lo, hi):
        """Return one of:
          - (None, None)         field absent or explicitly null → clear override
          - (int, None)          field is a valid clamped int   → write override
          - (None, error_str)    field is present but invalid   → 400
        We can't use `False` as a sentinel here (it would compare equal to 0
        which is a legitimate value for keep_recent_per_automation), hence
        the explicit (value, error) tuple. Floats with a non-zero fractional
        part are rejected explicitly so a typoed `1.9` doesn't get silently
        truncated to `1`; whole-number floats like `7.0` are accepted (the
        browser's number input can emit them)."""
        if key not in body or body.get(key) is None:
            return (None, None)
        raw = body.get(key)
        # Allow the JS form to send "" to mean "clear", same as null.
        if isinstance(raw, str) and raw.strip() == "":
            return (None, None)
        # Refuse bool — Python treats True/False as 1/0 ints and we don't
        # want a stray boolean payload to silently set retention to 1 day.
        if isinstance(raw, bool):
            return (None, f"{key} must be an integer")
        if isinstance(raw, float):
            if not raw.is_integer():
                return (None, f"{key} must be a whole number")
            n = int(raw)
        elif isinstance(raw, int):
            n = raw
        elif isinstance(raw, str):
            try:
                # int() rejects "1.9" outright, which is what we want for
                # string payloads — the browser sends digit strings.
                n = int(raw.strip())
            except ValueError:
                return (None, f"{key} must be an integer")
        else:
            return (None, f"{key} must be an integer")
        if n < lo or n > hi:
            return (None, f"{key} must be between {lo} and {hi}")
        return (n, None)

    days, err = _opt_clamped_int(
        "retention_days", 1, automations.RETENTION_DAYS_MAX
    )
    if err:
        return jsonify({"error": err}), 400
    keep, err = _opt_clamped_int(
        "keep_recent_per_automation", 0,
        automations.RETENTION_KEEP_RECENT_MAX,
    )
    if err:
        return jsonify({"error": err}), 400

    # UPSERT (rather than plain UPDATE) so the save succeeds even if the
    # singleton row was somehow deleted out-of-band — otherwise an UPDATE
    # would silently no-op and the GET that follows would re-seed a fresh
    # all-NULL row, dropping the values the admin just submitted.
    execute_db(
        """
        INSERT INTO automation_settings
            (id, retention_days, keep_recent_per_automation, updated_at)
        VALUES (1, %s, %s, NOW())
        ON CONFLICT (id) DO UPDATE
           SET retention_days = EXCLUDED.retention_days,
               keep_recent_per_automation = EXCLUDED.keep_recent_per_automation,
               updated_at = NOW()
        """,
        (days, keep),
    )
    return admin_automations_settings_get()


@app.route("/admin/api/automations", methods=["GET"])
@admin_required
def admin_automations_list():
    rows = query_db(
        "SELECT * FROM automations ORDER BY id DESC"
    ) or []
    return jsonify([_redact_automation_for_editor(_row_automation(r)) for r in rows])


@app.route("/admin/api/automations", methods=["POST"])
@admin_required
def admin_automations_create():
    try:
        payload = _validate_automation_payload(request.get_json(silent=True) or {})
    except ValueError as e:
        return jsonify({"error": str(e)}), 400
    # webhook_token is generated lazily — only when the automation actually
    # uses the webhook trigger — so non-webhook rows don't pollute the
    # unique index.
    token = automations.generate_webhook_token() if payload["trigger_type"] == "webhook" else ""
    row = execute_db(
        """
        INSERT INTO automations
            (name, description, enabled, trigger_type, trigger_config,
             action_steps, webhook_token)
        VALUES (%s, %s, %s, %s, %s::jsonb, %s::jsonb, %s)
        RETURNING *
        """,
        (
            payload["name"], payload["description"], payload["enabled"],
            payload["trigger_type"],
            json.dumps(payload["trigger_config"]),
            json.dumps(payload["action_steps"]),
            token,
        ),
    )
    _save_automation_version(
        row["id"], _automation_snapshot(payload), note="Created"
    )
    return jsonify(_redact_automation_for_editor(_row_automation(row))), 201


@app.route("/admin/api/automations/<int:aid>", methods=["GET"])
@admin_required
def admin_automations_get(aid):
    row = query_db("SELECT * FROM automations WHERE id = %s", (aid,), fetchone=True)
    if not row:
        return jsonify({"error": "Not found"}), 404
    return jsonify(_redact_automation_for_editor(_row_automation(row)))


@app.route("/admin/api/automations/<int:aid>", methods=["PUT"])
@admin_required
def admin_automations_update(aid):
    try:
        payload = _validate_automation_payload(request.get_json(silent=True) or {})
    except ValueError as e:
        return jsonify({"error": str(e)}), 400
    existing = query_db(
        "SELECT trigger_type, trigger_config, webhook_token FROM automations WHERE id = %s",
        (aid,), fetchone=True,
    )
    if not existing:
        return jsonify({"error": "Not found"}), 404
    # Preserve any masked-out trigger secret (e.g. signature_secret) the
    # admin didn't actively re-enter — the editor renders the input
    # blank so a vanilla save would otherwise wipe the stored secret.
    # Only safe to do when the trigger type didn't switch; otherwise the
    # leftover credential belongs to a different integration.
    if existing.get("trigger_type") == payload["trigger_type"]:
        _merge_preserved_trigger_secrets(
            payload["trigger_config"], existing.get("trigger_config") or {},
        )
    # Mint a webhook token the first time the trigger becomes 'webhook'.
    token = existing["webhook_token"] or ""
    if payload["trigger_type"] == "webhook" and not token:
        token = automations.generate_webhook_token()
    elif payload["trigger_type"] != "webhook":
        # Clear the token if the trigger was switched away from webhook so
        # any old URL stops working.
        token = ""
    row = execute_db(
        """
        UPDATE automations
           SET name=%s, description=%s, enabled=%s, trigger_type=%s,
               trigger_config=%s::jsonb, action_steps=%s::jsonb,
               webhook_token=%s, updated_at=NOW(),
               next_scheduled_at = CASE WHEN trigger_type <> %s THEN NULL ELSE next_scheduled_at END
         WHERE id=%s
        RETURNING *
        """,
        (
            payload["name"], payload["description"], payload["enabled"],
            payload["trigger_type"],
            json.dumps(payload["trigger_config"]),
            json.dumps(payload["action_steps"]),
            token,
            payload["trigger_type"],
            aid,
        ),
    )
    _save_automation_version(
        aid, _automation_snapshot(payload), note="Updated"
    )
    return jsonify(_redact_automation_for_editor(_row_automation(row)))


