    # two rows share a millisecond timestamp.
    rows = query_db(
        "SELECT * FROM automation_runs WHERE automation_id = %s "
        "ORDER BY queued_at DESC, id DESC LIMIT 100",
        (aid,),
    ) or []
    return jsonify([_row_run(r) for r in rows])


