@app.route("/admin/api/messaging/log")
@admin_required
def admin_messaging_log():
    """Recent log rows across all campaigns. Filterable by ?status= or ?channel=."""
    where = ["1=1"]
    params: list = []
    status = request.args.get("status")
    if status:
        where.append("status = %s")
        params.append(status)
    channel = request.args.get("channel")
    if channel:
        where.append("channel = %s")
        params.append(channel)
    sql = f"SELECT * FROM messaging_log WHERE {' AND '.join(where)} ORDER BY id DESC LIMIT 500"
    rows = query_db(sql, tuple(params)) or []
    return jsonify([_row_log(r) for r in rows])


# --- PUBLIC: webhooks --------------------------------------------------------

@app.route("/webhooks/resend", methods=["POST"])
def webhook_resend():
    """Handle Resend's webhook events. Resend signs with Svix; if no signing
    secret is configured we accept anyway and just log a warning so admins
    can wire up the endpoint before pasting the secret."""
    raw = request.get_data() or b""
    if not messaging.verify_resend_signature(dict(request.headers), raw):
        return jsonify({"error": "invalid signature"}), 401
    try:
        payload = json.loads(raw.decode("utf-8") or "{}")
    except (UnicodeDecodeError, json.JSONDecodeError):
        return jsonify({"error": "invalid payload"}), 400

    event_type = (payload.get("type") or "").strip().lower()
    data = payload.get("data") or {}
    email_id = (data.get("email_id") or data.get("id") or "").strip()
    if not email_id:
        return jsonify({"ok": True, "note": "no email id in payload"})

    log = query_db(
        "SELECT id FROM messaging_log WHERE provider_message_id=%s LIMIT 1",
        (email_id,),
        fetchone=True,
    )
    if not log:
        return jsonify({"ok": True, "note": "log row not found"})

    if event_type.endswith("delivered"):
        execute_db(
            "UPDATE messaging_log SET status='delivered', delivered_at=COALESCE(delivered_at, NOW()) WHERE id=%s",
            (log["id"],),
        )
    elif event_type.endswith("opened"):
        execute_db(
            """
            UPDATE messaging_log
               SET status = CASE WHEN status IN ('queued','sent','delivered') THEN 'opened' ELSE status END,
                   opened_at = COALESCE(opened_at, NOW()),
                   open_count = open_count + 1
             WHERE id=%s
            """,
            (log["id"],),
        )
    elif event_type.endswith("clicked"):
        execute_db(
            """
            UPDATE messaging_log
               SET status='clicked',
                   clicked_at = COALESCE(clicked_at, NOW()),
                   click_count = click_count + 1
             WHERE id=%s
            """,
            (log["id"],),
        )
    elif event_type.endswith("bounced"):
        reason = (data.get("bounce") or {}).get("message") or "bounced"
        execute_db(
            "UPDATE messaging_log SET status='bounced', error_text=%s WHERE id=%s",
            (str(reason)[:500], log["id"]),
        )
    elif event_type.endswith("complained"):
        execute_db(
            "UPDATE messaging_log SET status='complained' WHERE id=%s",
            (log["id"],),
        )
        # Honor the complaint by opting them out of email.
        execute_db(
            """
            UPDATE subscribers
               SET opt_in_email=FALSE
             WHERE id IN (SELECT subscriber_id FROM messaging_log WHERE id=%s)
            """,
            (log["id"],),
        )
    return jsonify({"ok": True})


@app.route("/webhooks/twilio/sms-status", methods=["POST"])
def webhook_twilio_status():
    """Twilio posts delivery status updates to this URL. Updates the
    matching messaging_log row by SID (which is the provider_message_id
    we stored at send time)."""
    form = request.form.to_dict(flat=True)
    sig = request.headers.get("X-Twilio-Signature", "")
    full_url = request.url  # Twilio signs the full URL we registered
    if not messaging.verify_twilio_signature(full_url, form, sig):
        return jsonify({"error": "invalid signature"}), 401
    sid = form.get("MessageSid", "")
    status = (form.get("MessageStatus") or "").lower()
    if not sid:
        return jsonify({"ok": True})
    mapping = {
        "queued": "sent",
        "sent": "sent",
        "delivered": "delivered",
        "failed": "failed",
        "undelivered": "failed",
    }
    new_status = mapping.get(status)
    if not new_status:
        return jsonify({"ok": True})

    # Twilio sometimes revises NumSegments on the delivered callback
    # (e.g. after re-encoding). Recompute the row's cost using the
    # SAME unit price that was stamped at insert time — never refresh
    # from current model_prices, otherwise an admin price edit would
    # retroactively rewrite history. If unit_sms_price_usd is NULL
    # (cost wasn't priceable when written), we leave cost_usd alone.
    raw_segs = form.get("NumSegments")
    if raw_segs:
        try:
            new_segs = int(raw_segs)
        except (TypeError, ValueError):
            new_segs = None
        # Pass Twilio's reported segment count through untouched — never
        # fabricate "1". Twilio sends NumSegments=0 during transitional
        # routing states (queued/sending) before the real count is
        # known; treat both 0 and unparseable values as "no authoritative
        # count yet" by skipping the UPDATE so the original send-side
        # value (or NULL) stands. Final delivered/failed callbacks carry
        # the real positive count, which then writes through.
        if new_segs and new_segs > 0:
            try:
                execute_db(
                    "UPDATE sms_cost_events "
                    "   SET segments = %s, "
                    "       cost_usd = CASE "
                    "         WHEN unit_sms_price_usd IS NOT NULL "
                    "           THEN %s * unit_sms_price_usd "
                    "         ELSE cost_usd "
                    "       END "
                    " WHERE message_sid = %s",
                    (new_segs, new_segs, sid),
                )
            except Exception as e:
                print(f"[cost] webhook segment update failed: {e}")

    if new_status == "delivered":
        execute_db(
            """
            UPDATE messaging_log
               SET status='delivered', delivered_at=COALESCE(delivered_at, NOW())
             WHERE provider_message_id=%s
            """,
            (sid,),
        )
    elif new_status == "failed":
        err = form.get("ErrorMessage") or form.get("ErrorCode") or "failed"
        execute_db(
            "UPDATE messaging_log SET status='failed', error_text=%s WHERE provider_message_id=%s",
            (str(err)[:500], sid),
        )
    else:
        execute_db(
            "UPDATE messaging_log SET status=%s WHERE provider_message_id=%s",
            (new_status, sid),
        )
    return jsonify({"ok": True})


@app.route("/webhooks/twilio/inbound-sms", methods=["POST"])
def webhook_twilio_inbound():
    """Public endpoint for Twilio's inbound-SMS webhook. We don't run a
    two-way inbox in v1, but we DO honor STOP/UNSUBSCRIBE keywords by
    flipping the matching subscriber's opt_in_sms flag so future SMS
    campaigns skip them. Twilio also enforces STOP at the carrier level,
    so this is a mirror, not the source of truth."""
    form = request.form.to_dict(flat=True)
    sig = request.headers.get("X-Twilio-Signature", "")
    if not messaging.verify_twilio_signature(request.url, form, sig):
        return Response("<Response/>", status=401, mimetype="application/xml")
    from_num = (form.get("From") or "").strip()
    body_text = (form.get("Body") or "").strip().lower()
    keywords = {"stop", "stopall", "unsubscribe", "cancel", "end", "quit"}
    if from_num and body_text in keywords:
        execute_db(
            """
            UPDATE subscribers
               SET opt_in_sms = FALSE,
                   unsubscribed_at = COALESCE(unsubscribed_at, NOW())
             WHERE phone = %s
            """,
            (from_num,),
        )
    # Twilio expects TwiML in the response. Empty <Response/> = no auto-reply.
    return Response("<Response/>", mimetype="application/xml")


# --- PUBLIC: Twilio Voice (live AI phone call — task 049) -------------------
# Inbound-call webhook + status callback. Signature-verified like the SMS
# webhooks. The live media bridge (Twilio <Connect><Stream> ↔ a realtime voice
# model over wss) is the credential/infra leg — deferred to an operator runbook;
# point your Twilio Voice number's webhook at /webhooks/twilio/voice and set
# voice_wss_url to your media-stream endpoint. With no wss configured, callers
# get a spoken fallback. Everything is gated by 'live_call_enabled'.

def _twiml(inner):
    return Response(f'<?xml version="1.0" encoding="UTF-8"?><Response>{inner}</Response>',
                    mimetype="text/xml")


def _twilio_auth_configured():
    """True when TWILIO_AUTH_TOKEN is set. verify_twilio_signature FAILS OPEN
    without it (handy for SMS dev), but the voice endpoints have side effects +
    route real calls, so they FAIL CLOSED when it's missing — a misconfigured
    host can't be used to spoof calls / status."""
    return bool((os.environ.get("TWILIO_AUTH_TOKEN") or "").strip())


@app.route("/webhooks/twilio/voice", methods=["POST"])
def webhook_twilio_voice():
    """Inbound Twilio Voice webhook. Returns TwiML. When live calling is enabled
    AND a media-stream endpoint is configured, connect the call to the streaming
    voice bot; otherwise speak a fallback. Logs a voice_calls row."""
    form = request.form.to_dict(flat=True)
    sig = request.headers.get("X-Twilio-Signature", "")
    # Fail CLOSED if Twilio auth isn't configured (signature check would
    # otherwise fail-open and let anyone spoof a call). Voice has side effects.
    if not _twilio_auth_configured():
        return _twiml("<Reject/>")
    if not messaging.verify_twilio_signature(request.url, form, sig):
        return _twiml("<Reject/>")
    esc = lambda s: html_module.escape(str(s or ""), quote=True)
    if not get_ai_setting("live_call_enabled"):
        # Politely decline — feature off.
        return _twiml("<Say>Sorry, live calling is not available right now. "
                      "Goodbye.</Say><Hangup/>")
    # Log the inbound call (best-effort; never block the TwiML response).
    try:
        execute_db(
            "INSERT INTO voice_calls (tenant_id, call_sid, from_number, to_number, status) "
            "VALUES (%s,%s,%s,%s,'in-progress')",
            (current_tenant_id(), (form.get("CallSid") or "")[:64],
             form.get("From") or "", form.get("To") or ""))
    except Exception as e:
        print(f"[voice] call log failed: {type(e).__name__}: {e}")
    greeting = (get_ai_setting("voice_greeting") or "").strip() or "Hello!"
    wss = (get_ai_setting("voice_wss_url") or "").strip()
    if wss and wss.lower().startswith("wss://"):
        # Live media bridge — stream the call to the realtime voice model.
        return _twiml(
            f"<Say>{esc(greeting)}</Say>"
            f'<Connect><Stream url="{esc(wss)}"/></Connect>')
    # No media endpoint configured → spoken fallback (no live AI voice yet).
    return _twiml(
        f"<Say>{esc(greeting)}</Say>"
        "<Say>Our live assistant is not fully set up yet. Please leave us a "
        "message after the tone, or contact us through our website.</Say>"
        "<Hangup/>")


@app.route("/webhooks/twilio/voice-status", methods=["POST"])
def webhook_twilio_voice_status():
    """Twilio Voice status callback — updates the call's status."""
    form = request.form.to_dict(flat=True)
    sig = request.headers.get("X-Twilio-Signature", "")
    if not _twilio_auth_configured():
        return Response("<Response/>", status=401, mimetype="text/xml")
    if not messaging.verify_twilio_signature(request.url, form, sig):
        return Response("<Response/>", status=401, mimetype="text/xml")
    sid = (form.get("CallSid") or "")[:64]
    status = (form.get("CallStatus") or "").strip()[:40]
    if sid and status:
        try:
            execute_db(
                "UPDATE voice_calls SET status=%s, updated_at=NOW() "
                "WHERE call_sid=%s", (status, sid))
        except Exception as e:
            print(f"[voice] status update failed: {type(e).__name__}: {e}")
    return Response("<Response/>", mimetype="text/xml")


@app.route("/admin/api/voice-calls", methods=["GET"])
@admin_required
def admin_list_voice_calls():
    """Inbound AI voice calls (super-admin only)."""
    guard = _require_super_admin_role()
    if guard:
        return guard
    try:
        limit = max(1, min(int(request.args.get("limit", 100) or 100), 500))
    except (TypeError, ValueError):
        limit = 100
    tid = current_tenant_id()
    rows = query_db(
        "SELECT id, call_sid, from_number, to_number, status, summary, created_at "
        "FROM voice_calls WHERE tenant_id=%s ORDER BY id DESC LIMIT %s",
        (tid, limit)) or []
    return jsonify({"calls": [_iso_row(r, "created_at") for r in rows]})


# --- PUBLIC: unsubscribe ----------------------------------------------------

@app.route("/unsubscribe")
def public_unsubscribe():
    """One-click unsubscribe page. Honors GET (link click) and POST
    (RFC 8058 List-Unsubscribe-Post). Token is HMAC-signed so subscribers
    cannot opt each other out by guessing IDs."""
    token = request.args.get("token") or ""
    sub_id = messaging.parse_unsubscribe_token(token)
    if not sub_id:
        return Response(
            _unsubscribe_page("Invalid or expired unsubscribe link."),
            status=400, mimetype="text/html",
        )
    row = execute_db(
        """
        UPDATE subscribers
           SET opt_in = FALSE,
               opt_in_email = FALSE,
               unsubscribed_at = COALESCE(unsubscribed_at, NOW())
         WHERE id = %s
        RETURNING email, full_name
        """,
        (sub_id,),
    )
    name = row.get("email") or row.get("full_name") if row else "you"
    return Response(
        _unsubscribe_page(
            f"You've been unsubscribed. We won't send any more email to {html_module.escape(name or '')}."
        ),
        mimetype="text/html",
    )


@app.route("/unsubscribe", methods=["POST"])
def public_unsubscribe_post():
    return public_unsubscribe()


def _unsubscribe_page(message: str) -> str:
    return (
        '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8">'
        '<meta name="viewport" content="width=device-width, initial-scale=1.0">'
        '<title>Unsubscribed</title>'
        '<style>'
        'body{font-family:-apple-system,Segoe UI,Roboto,sans-serif;background:#0f172a;color:#e4e4e7;'
        'min-height:100vh;display:flex;align-items:center;justify-content:center;margin:0;padding:1.5rem}'
        '.card{max-width:480px;background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.08);'
        'padding:2rem;border-radius:0.75rem;text-align:center}'
        'h1{font-size:1.25rem;margin:0 0 0.75rem 0}p{color:rgba(255,255,255,0.7);margin:0}'
        '</style></head><body>'
        f'<div class="card"><h1>Unsubscribe</h1><p>{message}</p></div>'
        '</body></html>'
    )


# =============================================================================
# SELF-SERVICE PREFERENCES PORTAL  (Phase 6 / Epic D — task 043)
# =============================================================================
# A public, token-signed page where a subscriber manages their own contact
# preferences (email / SMS opt-in) or unsubscribes entirely. The token is an
# HMAC capability scoped to one subscriber id (messaging.make_prefs_token) — no
# login, no session, so the global /admin CSRF guard doesn't apply (the token
# IS the capability, exactly like the existing /unsubscribe link).

def _prefs_url(subscriber_id: int) -> str:
    base = _public_base_url() or ""
    return f"{base}/preferences?token={messaging.make_prefs_token(subscriber_id)}"


def _prefs_page(*, message="", sub=None, token="", done=False) -> str:
    """Render the preferences page. When `sub` is None we show an error card.
    Escapes all subscriber-derived text."""
    esc = lambda s: html_module.escape(str(s or ""), quote=True)
    head = (
        '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8">'
        '<meta name="viewport" content="width=device-width, initial-scale=1.0">'
        '<title>Email preferences</title><style>'
        'body{font-family:-apple-system,Segoe UI,Roboto,sans-serif;background:#0f172a;color:#e4e4e7;'
        'min-height:100vh;display:flex;align-items:center;justify-content:center;margin:0;padding:1.5rem}'
        '.card{max-width:480px;width:100%;background:rgba(255,255,255,0.05);'
        'border:1px solid rgba(255,255,255,0.08);padding:2rem;border-radius:0.75rem}'
        'h1{font-size:1.25rem;margin:0 0 0.5rem 0}p{color:rgba(255,255,255,0.7)}'
        'label{display:flex;align-items:center;gap:0.6rem;margin:0.9rem 0;cursor:pointer}'
        'button{margin-top:1rem;padding:0.6rem 1rem;border-radius:0.5rem;border:none;cursor:pointer;'
        'font-size:0.95rem}.save{background:#6366f1;color:#fff}.unsub{background:transparent;'
        'color:#f87171;border:1px solid rgba(248,113,113,0.4);margin-left:0.5rem}'
        '.muted{font-size:0.8rem;color:rgba(255,255,255,0.45)}'
        '</style></head><body><div class="card">'
    )
    tail = '</div></body></html>'
    if sub is None:
        return head + '<h1>Email preferences</h1><p>' + esc(message or "Invalid or expired link.") + '</p>' + tail
    note = f'<p style="color:#34d399">{esc(message)}</p>' if (message and done) else ''
    email_checked = "checked" if sub.get("opt_in_email") else ""
    sms_checked = "checked" if sub.get("opt_in_sms") else ""
    has_phone = bool((sub.get("phone") or "").strip())
    sms_row = (
        f'<label><input type="checkbox" name="opt_in_sms" {sms_checked}> Text messages (SMS)</label>'
        if has_phone else ''
    )
    return (
        head
        + '<h1>Your email preferences</h1>'
        + f'<p>Managing preferences for <strong>{esc(sub.get("email"))}</strong></p>'
        + note
        + f'<form method="POST" action="/preferences">'
        + f'<input type="hidden" name="token" value="{esc(token)}">'
        + f'<label><input type="checkbox" name="opt_in_email" {email_checked}> Email updates &amp; newsletter</label>'
        + sms_row
        + '<div><button class="save" type="submit" name="action" value="save">Save preferences</button>'
        + '<button class="unsub" type="submit" name="action" value="unsubscribe">Unsubscribe from everything</button></div>'
        + '<p class="muted">You received this link because you subscribed. We never share your address.</p>'
        + '</form>'
        + tail
    )


def _prefs_portal_unavailable():
    """Fail-closed response when the signing secret is the insecure dev
    fallback (tokens would be forgeable — see signing_secret_is_insecure)."""
    return Response(
        _prefs_page(message="The preferences portal isn't available on this "
                            "server right now. Please contact us to update your "
                            "preferences."),
        status=503, mimetype="text/html")


@app.route("/preferences", methods=["GET"])
def public_preferences():
    """Show a subscriber their current contact preferences (signed token)."""
    if messaging.signing_secret_is_insecure():
        return _prefs_portal_unavailable()
    token = request.args.get("token") or ""
    sub_id = messaging.parse_prefs_token(token)
    if not sub_id:
        return Response(_prefs_page(message="This preferences link is invalid or expired."),
                        status=400, mimetype="text/html")
    row = query_db(
        "SELECT id, email, phone, opt_in, opt_in_email, opt_in_sms "
        "FROM subscribers WHERE id=%s", (sub_id,), fetchone=True)
    if not row:
        return Response(_prefs_page(message="We couldn't find that subscription."),
                        status=404, mimetype="text/html")
    return Response(_prefs_page(sub=row, token=token), mimetype="text/html")


@app.route("/preferences", methods=["POST"])
def public_preferences_post():
    """Apply a subscriber's preference changes (signed token in the form)."""
    if messaging.signing_secret_is_insecure():
        return _prefs_portal_unavailable()
    token = request.form.get("token") or ""
    sub_id = messaging.parse_prefs_token(token)
    if not sub_id:
        return Response(_prefs_page(message="This preferences link is invalid or expired."),
                        status=400, mimetype="text/html")
    action = (request.form.get("action") or "save").strip().lower()
    if action == "unsubscribe":
        opt_email, opt_sms = False, False
    else:
        # Unchecked checkboxes are simply absent from the form post.
        opt_email = request.form.get("opt_in_email") is not None
        opt_sms = request.form.get("opt_in_sms") is not None
    master = bool(opt_email or opt_sms)
    row = execute_db(
        "UPDATE subscribers SET opt_in=%s, opt_in_email=%s, opt_in_sms=%s, "
        "  unsubscribed_at = CASE WHEN %s THEN NULL "
        "                         ELSE COALESCE(unsubscribed_at, NOW()) END, "
        "  updated_at = NOW() "
        "WHERE id=%s RETURNING id, email, phone, opt_in, opt_in_email, opt_in_sms",
        (master, opt_email, opt_sms, master, sub_id))
    if not row:
        return Response(_prefs_page(message="We couldn't find that subscription."),
                        status=404, mimetype="text/html")
    msg = ("You've been unsubscribed from everything."
           if not master else "Your preferences have been saved.")
    return Response(_prefs_page(sub=row, token=token, message=msg, done=True),
                    mimetype="text/html")


# =============================================================================
# PLANS & FEATURES — admin endpoints
# =============================================================================
# Backs the "Plans & Features" tab in the dashboard. Lists every feature in
# _FEATURE_REGISTRY together with whether the current tenant has it enabled,
# and lets an admin flip the toggle. The flip writes through to tenant_features
# and busts the in-process cache so the change is live on the very next request.

@app.route("/admin/api/tenant/features", methods=["GET"])
@admin_required
def admin_list_tenant_features():
    """Return every known feature + on/off state + plan tier + addon flag."""
    # HARD boundary: only the super admin manages feature visibility. A client
    # session is logged-in (passes @admin_required) but must never read or change
    # the feature roster — this is what stops a client from re-granting itself
    # tabs by hitting the API directly, independent of the hidden UI tab.
    _guard = _require_super_admin_role()
    if _guard is not None:
        return _guard
    try:
        tid = current_tenant_id()
        # Pull plan + tenant info so the UI can show "you're on the Growth plan".
        # NOTE: the plans table has columns (id, slug, name, description,
        # sort_order). We expose `slug` as `plan_code` for UI back-compat.
        tenant = query_db(
            "SELECT t.id, t.name AS tenant_name, t.plan_id, "
            "       p.slug AS plan_code, p.name AS plan_name "
            "FROM tenants t LEFT JOIN plans p ON p.id = t.plan_id "
            "WHERE t.id = %s",
            (tid,), fetchone=True,
        ) or {}
        features = list_tenant_features(tid)
        plans = query_db(
            "SELECT id, slug AS code, name, description, sort_order "
            "FROM plans ORDER BY sort_order, id"
        ) or []
        return jsonify({
            "tenant": dict(tenant) if tenant else {"id": tid},
            "features": features,
            "plans": [dict(p) for p in plans],
        })
    except Exception as e:
        print(f"[plans] list_tenant_features failed: {e}")
        return jsonify({"error": "failed_to_list_features", "detail": str(e)}), 500


@app.route("/admin/api/tenant/features/<name>", methods=["PATCH"])
@admin_required
def admin_toggle_tenant_feature(name):
    """Flip one feature on/off. Body: {"enabled": bool, "note"?: str}."""
    # HARD boundary: super admin only (see admin_list_tenant_features). Without
    # this in-handler check a client could PATCH its own flags via curl.
    _guard = _require_super_admin_role()
    if _guard is not None:
        return _guard
    body = request.get_json(silent=True) or {}
    if "enabled" not in body:
        return jsonify({"error": "missing_field", "field": "enabled"}), 400
    try:
        new_val = set_tenant_feature(
            name,
            bool(body.get("enabled")),
            note=str(body.get("note") or ""),
        )
        return jsonify({"feature": name, "enabled": new_val})
    except ValueError as ve:
        return jsonify({"error": "unknown_feature", "feature": name, "detail": str(ve)}), 400
    except Exception as e:
        print(f"[plans] toggle feature {name} failed: {e}")
        return jsonify({"error": "toggle_failed", "detail": str(e)}), 500


# --- Scheduler boot ----------------------------------------------------------
# We defer scheduler startup to the first incoming request rather than running
# it at import time. Flask's debug reloader runs the module in TWO processes
# (the watcher parent + the spawned child); only the child actually serves
# requests, so wiring this to the request lifecycle guarantees we start the
# loop exactly once in dev. Under gunicorn, the first request after each
# worker boot triggers it. messaging.start_scheduler() is idempotent so the
# overhead per-request is just a flag check.
@app.before_request
def _ensure_messaging_scheduler():
    if not messaging._SCHEDULER_STARTED:
        messaging.start_scheduler()


# =============================================================================
# VELO MASTER AI HOOKS
# =============================================================================
# Mounts the /api/velo/* blueprint that VELO Master calls into, imports
# velo_handlers (which registers all @velo_command capabilities), and
# fires register_with_velo() on a background thread so a slow / missing
# VELO master can never block boot. All three steps run at module level
# so they apply under gunicorn as well as `python app.py`.
from velo_endpoints import velo_bp, get_registered_capabilities  # noqa: E402
import velo_handlers  # noqa: F401, E402  — import side-effect registers handlers
app.register_blueprint(velo_bp)


def _resolve_velo_callback_url():
    """Pick the public URL VELO Master should call back to for /api/velo/command.

    Priority:
      1. SITE_URL env var, **only if** it's a real http(s) URL that isn't
         localhost / 127.0.0.1 (master can't reach localhost on this box).
      2. PUBLIC_BASE_URL env var (the new canonical name) under the same
         localhost guard. Works on any host.
      3. https://<first entry of REPLIT_DOMAINS> — Replit's runtime-managed
         public hostname. Works in both dev and deployed instances.
      4. SITE_URL as-is (even if localhost) for pure-local testing.

    Returning a base origin (no trailing slash, no path).
    """
    explicit = os.environ.get("SITE_URL", "").strip().rstrip("/")
    is_localish = (
        not explicit
        or "localhost" in explicit
        or "127.0.0.1" in explicit
    )
    if not is_localish:
        return explicit
    public = os.environ.get("PUBLIC_BASE_URL", "").strip().rstrip("/")
    if public and "localhost" not in public and "127.0.0.1" not in public:
        return public
    domains = os.environ.get("REPLIT_DOMAINS", "").strip()
    if domains:
        first = domains.split(",")[0].strip()
        if first:
            return f"https://{first}"
    return explicit or "http://localhost:5000"


def register_with_velo(force=False):
    """Tell VELO Master what this install can do.

    Posts the full capability list once for each agent_id this install
    serves (admin_ai + visitor_ai both route to the same /api/velo/command
    endpoint — they're separate logical agents from VELO's perspective).

    Sends the explicit callback URL in **three** field names (`endpoint`,
    `command_endpoint`, `callback_url`) so the master gateway honors it
    regardless of which field name its parser expects, instead of falling
    back to the auto-derived `/api/velo/<agent_id>` pattern (which doesn't
    exist on this app — every agent shares one /api/velo/command route).

    `force=True` is used by /api/velo/refresh-registration to re-publish
    capabilities at runtime (e.g. after enabling a new feature group)
    without restarting the worker. The boot-time path leaves it default.

    Returns a small dict summarising what happened so callers like the
    refresh endpoint can echo it back. Failure modes stay silent-ish:
    missing VELO_MASTER_URL is a no-op; network errors get printed but
    never raised. Boot must never block on VELO availability.
    """
    result = {"forced": bool(force), "client_registered": False, "agents": {}}
    velo_url = os.environ.get("VELO_MASTER_URL", "").strip()
    if not velo_url:
        print("[velo] VELO_MASTER_URL not set — skipping master registration.")
        result["skipped"] = "VELO_MASTER_URL not set"
        return result
    agent_key = os.environ.get("VELO_AGENT_KEY", "").strip()
    site_url = _resolve_velo_callback_url()
    command_url = f"{site_url}/api/velo/command"
    chat_url = f"{site_url}/api/velo/chat"
    capabilities = get_registered_capabilities()
    result["capability_count"] = len(capabilities)
    result["site_url"] = site_url
    print(f"[velo] callback site_url={site_url} → {command_url} "
          f"({len(capabilities)} capabilities, force={force})")
    headers = {"Authorization": f"Bearer {agent_key}", "Content-Type": "application/json"}
    import requests as _requests

    # Step 1 — register THIS install as a managed client of VELO Master.
    # The master needs to know us as a client (Admin → Clients tab, health
    # checks, feature gating) before agent registrations are meaningful.
    # Failure is logged but does not abort the agent-register step below —
    # if the client is already known, /api/agent-register still works.
    try:
        resp = _requests.post(
            f"{velo_url}/api/clients/register",
            headers=headers,
            json={
                "client_id": "replit-flask-app",
                "client_name": "AI Concierge Platform",
                "velo_url": site_url,
                "site_url": site_url,
                "agent_key": agent_key,
            },
            timeout=10,
        )
        resp.raise_for_status()
        print(f"[velo] registered as client at {velo_url}")
        result["client_registered"] = True
    except Exception as e:
        print(f"[velo] client registration failed: {e}")
        result["client_error"] = str(e)

    # Step 2 — register each logical agent. Both share the same single
    # /api/velo/command endpoint on this side; the gateway gets the URL
    # under three field names so it never falls back to auto-derivation.
    for agent_type in ("admin_ai", "visitor_ai"):
        try:
            resp = _requests.post(
                f"{velo_url}/api/agent-register",
                headers=headers,
                json={
                    "agent_id": agent_type,
                    "agent_type": agent_type,
                    "client_id": "replit-flask-app",
                    "base_url": site_url,
                    "endpoint": command_url,
                    "command_endpoint": command_url,
                    "callback_url": command_url,
                    "chat_endpoint": chat_url,
                    "capabilities": capabilities,
                    "metadata": {"framework": "flask", "version": "1.0"},
                },
                timeout=10,
            )
            resp.raise_for_status()
            print(
                f"[velo] registered {agent_type} with {len(capabilities)} "
                f"capabilities → {command_url}"
            )
            result["agents"][agent_type] = "ok"
        except Exception as e:
            print(f"[velo] failed to register {agent_type}: {e}")
            result["agents"][agent_type] = f"error: {e}"

    return result


# Run registration exactly once per worker, on the first request that
# worker handles. Mirrors the messaging-scheduler pattern above and
# avoids three traps:
#   • Flask's debug reloader runs the module twice (parent + child); only
#     the child actually serves requests, so this gate runs once in dev.
#   • Under gunicorn each worker hits this once after fork — desirable,
#     since master should accept idempotent re-registers.
#   • Boot is never delayed: registration runs on a daemon thread.
_VELO_REGISTRATION_TRIGGERED = False
_VELO_REGISTRATION_LOCK = threading.Lock()


@app.before_request
def _ensure_velo_registration():
    global _VELO_REGISTRATION_TRIGGERED
    if _VELO_REGISTRATION_TRIGGERED:
        return
    with _VELO_REGISTRATION_LOCK:
        if _VELO_REGISTRATION_TRIGGERED:
            return
        _VELO_REGISTRATION_TRIGGERED = True
        threading.Thread(
            target=register_with_velo,
            daemon=True,
            name="velo-register",
        ).start()


# =============================================================================
# APP ENTRY POINT
# =============================================================================


def _run_alembic_upgrade() -> None:
    """Apply pending Alembic migrations, called once at boot after init_db().

    Two-track schema management (see init_db's preamble for the full
    contract): init_db owns historical tables; Alembic owns everything
    added after April 2026. Running upgrade-to-head on every boot is
    cheap — Alembic just queries `alembic_version` and no-ops when
    already at head — and keeps the running app's schema in lockstep
    with the deployed code.

    Behaviour:
      * On a brand-new DB, init_db has just created the historical
        tables. Alembic finds no `alembic_version` table, creates it,
        runs the empty 0001_baseline migration, and stamps the row.
      * On an existing DB without Alembic state, same flow as above —
        the baseline migration is a no-op so this is purely bookkeeping.
      * On an existing DB already at head, the upgrade is a single
        SELECT against `alembic_version` and exits.
      * On a DB behind head, every pending revision runs in order.

    A migration failure is fatal: the running code expects whatever
    schema HEAD defines, so coming up against a stale DB would lead to
    mid-request 500s that are much harder to diagnose than a loud boot
    failure. Set `SKIP_ALEMBIC=1` to bypass for emergency recovery (e.g.
    rolling back a bad release while the bad migration is still in the
    revision tree).
    """
    if os.environ.get("SKIP_ALEMBIC", "").strip().lower() in ("1", "true", "yes"):
        print("[alembic] skipped (SKIP_ALEMBIC set)", file=sys.stderr)
        return

    # Lazy import so projects that never run this codepath (e.g. one-off
    # scripts that only `from app import some_helper`) don't pay the
    # ~80ms alembic + sqlalchemy import cost.
    try:
        from alembic.config import Config as _AlembicConfig
        from alembic import command as _alembic_command
    except ImportError as exc:
        raise RuntimeError(
            "alembic is not installed but is required for schema migrations; "
            "run `uv add alembic` or set SKIP_ALEMBIC=1 to bypass"
        ) from exc

    cfg_path = os.path.join(
        os.path.dirname(os.path.abspath(__file__)), "alembic.ini")
    if not os.path.exists(cfg_path):
        raise RuntimeError(
            f"alembic.ini not found at {cfg_path} — Alembic scaffolding is "
            "missing; restore from version control or set SKIP_ALEMBIC=1")

    cfg = _AlembicConfig(cfg_path)
    _alembic_command.upgrade(cfg, "head")
    print("[alembic] migrations up to date", file=sys.stderr)


if __name__ == "__main__":
    init_db()
    _run_alembic_upgrade()
    sync_skills_to_db()
    sync_custom_skills_to_agent_skills()
    # Seed admin_chat_sessions rows for any historical session_id that
    # only lives in admin_chat_messages, so the new sidebar shows
    # pre-existing conversations on first boot after this upgrade.
    _backfill_admin_chat_sessions()
    # Pre-fill the ai_prompts table with current defaults so the super-admin
    # "AI Prompts" editor is never empty (mirrors main._bootstrap()).
    sync_ai_prompts()
    app.run(host="0.0.0.0", port=5000, debug=True)
